window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[234]={"id":"234","numero":234,"titre":"Insuffisance cardiaque de l'adulte","objectifs":[{"id":"234-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de l’insuffisance cardiaque","contenu":"<div class=\"notion-course\"><p>L’<span class=\"nc-red nc-bold\">insuffisance cardiaque</span> est fréquente et sa prévalence augmente fortement avec l’<span class=\"nc-red_bg\">âge</span>. Le repère de 1–2 % chez l’adulte varie selon les populations et les définitions ; la charge de maladie croît avec le vieillissement et la survie après événements cardiovasculaires.</p><ul><li>L’IC à FE préservée concerne souvent des personnes âgées avec HTA, <span class=\"nc-green_bg\">obésité</span>, <span class=\"nc-orange\">diabète</span>, maladie rénale et FA ; les femmes y sont fréquemment représentées.</li><li>L’IC à FE réduite est souvent liée à une maladie coronaire ou une cardiomyopathie ; les comorbidités y sont également fréquentes.</li><li><span class=\"nc-green nc-bold\">Mortalité</span> et réhospitalisations sont élevées, mais les chiffres de <span class=\"nc-red nc-bold\">10 % à 1 an</span>/<span class=\"nc-red nc-bold\">50 % à 5 ans</span> sont des repères de cohortes, pas un pronostic individuel.</li><li>Il existe désormais des traitements validés également dans l’IC à FE préservée : l’affirmation « aucun traitement » est obsolète.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e79dc8c62b3d434362?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Choc cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":1},{"id":"234-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","contenu":"<div class=\"notion-course\"><p>L’IC est un syndrome clinique associant <span class=\"nc-blue_bg\">symptômes</span> (dyspnée, fatigue, œdèmes) et parfois signes (crépitants, <span class=\"nc-blue_bg\">turgescence jugulaire</span>), dus à une anomalie cardiaque structurelle/fonctionnelle. Le cœur assure un débit insuffisant et/ou nécessite des pressions de <span class=\"nc-red nc-bold\">remplissage</span> élevées, au <span class=\"nc-red nc-bold\">repos</span> ou <span class=\"nc-red nc-bold\">à l’effort</span>.</p><h4>Repères du collège — classification antérieure à 2026</h4><table><thead><tr><th>Phénotype</th><th>FEVG</th></tr></thead><tbody><tr><td>Réduite</td><td>≤ 40 %</td></tr><tr><td>Légèrement réduite / intermédiaire</td><td>41–49 %</td></tr><tr><td>Préservée</td><td>≥ 50 %</td></tr></tbody></table><div class=\"callout\"><p><b>Actualisation ESC 2026.</b> Deux phénotypes : FEVG &lt; 50 % (HFrEF) et FEVG ≥ 50 % (HFpEF). La catégorie 41–49 % est intégrée à HFrEF. Les anciens seuils du collège restent indiqués comme repères pédagogiques datés ; ne pas mélanger les classifications.</p></div><h4>FE préservée : un diagnostic positif</h4><ul><li><span class=\"nc-blue_bg\">Symptômes</span>/signes compatibles et FEVG ≥ 50 %, avec arguments objectifs de dysfonction/pressions de <span class=\"nc-red nc-bold\">remplissage</span> élevées : échographie, <span class=\"nc-pink_bg\">peptides natriurétiques</span>, parfois exploration <span class=\"nc-red nc-bold\">à l’effort</span> ou hémodynamique.</li><li>Une <span class=\"nc-blue nc-bold\">FEVG</span> normale ne prouve pas une fonction cardiaque entièrement normale. <span class=\"nc-pink_bg nc-bold\">BNP</span>/<span class=\"nc-green_bg nc-bold\">NT-proBNP</span> peuvent être peu élevés chez une personne obèse.</li><li>Troubles systoliques et diastoliques peuvent coexister ; les catégories ne se réduisent pas à « <span class=\"nc-red nc-bold\">contraction</span> » contre « <span class=\"nc-red nc-bold\">remplissage</span> ».</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details>","frequence":1},{"id":"234-3","rang":"A","rubrique":"Définition","titre":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","contenu":"<div class=\"notion-course\"><p>L'<span>œdème aigu pulmonaire (OAP) cardiogénique</span> est la manifestation <strong>la plus fréquente de l'<span><span class=\"nc-red nc-bold\">insuffisance cardiaque</span> aiguë</span></strong>. Il survient lorsque du liquide plasmatique diffuse dans les espaces extravasculaires pulmonaires (interstitium, alvéole).</p>\n      <p>Mécanisme <span>hémodynamique</span>, en chaîne :</p>\n      <ul>\n        <li>L'IC entraîne une augmentation brutale des <span>pressions de <span class=\"nc-red nc-bold\">remplissage</span></span> <span class=\"nc-yellow_bg\">du ventricule</span> gauche.</li>\n        <li>↑ <span class=\"nc-blue_bg\">pression dans l'</span>oreillette gauche et les capillaires pulmonaires (<span>PCP normale 7-12 mmHg</span>).</li>\n        <li>L’élévation de <span class=\"nc-red\">pression</span> hydrostatique pulmonaire dépasse les capacités de drainage lymphatique et favorise le passage de liquide vers interstitium puis alvéoles. Le seuil dépend du terrain : pas de valeur de PCP obligatoire pour diagnostiquer un OAP.</li>\n        <li>Les alvéoles sont « inondées », l'hématose est altérée → <span><span class=\"nc-red nc-bold\">hypoxémie</span></span> (<span><span class=\"nc-red nc-bold\">shunt vrai fonctionnel</span></span>).</li>\n        <li><span class=\"nc-yellow_bg\">Mécanisme compensatoire : </span><span><span class=\"nc-yellow_bg\">hyperventilation</span></span> → hypocapnie initiale.</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 En cas de résolution rapide, on parle de <strong>sub-<span>œdème</span> pulmonaire</strong> : il a la <strong>même valeur sémiologique</strong> que l'<span>OAP</span> et reste une <span>urgence</span> (risque d'<span>évolution</span> vers la <span>détresse respiratoire</span> ou le collapsus).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span>Détresse</span> et <span>insuffisance respiratoire</span> aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":1},{"id":"234-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition du choc cardiogénique","contenu":"<div class=\"notion-course\"><p>Le choc cardiogénique est une défaillance de pompe entraînant une hypoperfusion tissulaire et des défaillances d’organes. <span class=\"nc-orange_bg\">Hypotension</span>, marbrures, extrémités froides, oligurie, confusion et lactate élevé orientent, mais une PA encore préservée n’exclut pas un choc débutant.</p><ul><li>Infarctus, décompensation d’IC, <span class=\"nc-pink nc-bold\">myocardite</span>, arythmie ou complication mécanique/valvulaire sont des causes importantes. Leur proportion dépend de la population.</li><li>Repères hémodynamiques classiques : <span class=\"nc-blue_bg\">index cardiaque</span> <span class=\"nc-pink nc-bold\">&lt;</span><span class=\"nc-pink nc-bold\"> 2,2 L/min/m²</span> et pressions de remplissage élevées, souvent <span class=\"nc-pink nc-bold\">PAPO &gt; 15 mmHg</span>. Ils ne sont pas tous obligatoires, notamment dans l’atteinte droite.</li><li>Ne pas attendre 30 minutes d’<span class=\"nc-orange_bg\">hypotension</span> ni un cathétérisme pour traiter. Évaluer volémie et congestion ; pas de remplissage <span class=\"nc-red nc-bold\">systématique</span> destiné à « prouver » le diagnostic.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e79dc8c62b3d434362?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Choc cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":0},{"id":"234-5","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiopathologie de l’IC (gauche et droite)","contenu":"<div class=\"notion-course\"><p>Le <span>débit cardiaque</span> (DC) dépend du volume d'éjection systolique (<span><span class=\"nc-blue_bg\">VES = VTD − VTS</span></span>) et de la fréquence cardiaque. Le VES dépend de trois paramètres : la <span><span class=\"nc-yellow_bg nc-bold\">précharge</span></span> (degré de <span class=\"nc-red nc-bold\">remplissage</span> du VG, ≈ <span>VTD</span>), l'<span><span class=\"nc-red nc-bold\">inotropisme</span></span> (contractilité, sous dépendance β-adrénergique) et la <span>postcharge</span> (forces s'opposant à l'éjection).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/physiopath-cycle-vg.png\" alt=\"Cycle pression-volume du ventricule gauche — remplissage, contraction isovolumique, éjection, relaxation isovolumique\" loading=\"lazy\">\n        <figcaption>Cycle pression-volume du ventricule gauche : le VES correspond à la différence entre <span>VTD</span> (volume télédiastolique, précharge) et <span>VTS</span> (volume télésystolique). Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <p>Deux mécanismes d'<span class=\"nc-yellow_bg nc-bold\">IC gauche</span>, selon le paramètre intrinsèque atteint :</p>\n      <table>\n        <thead><tr><th></th><th>Atteinte de l'<span class=\"nc-red nc-bold\">inotropisme</span></th><th>Atteinte de la <span class=\"nc-red nc-bold\">compliance</span></th></tr></thead>\n        <tbody>\n          <tr><td>Type d'IC</td><td>IC à <span>FEVG altérée</span> (systolique)</td><td><span class=\"nc-green_bg\">IC à </span><span><span class=\"nc-green_bg\">FEVG préservée</span></span> (diastolique)</td></tr>\n          <tr><td>Causes</td><td><span><span class=\"nc-orange nc-bold\">Infarctus</span></span> ++, <span><span class=\"nc-red nc-bold\">myocardite</span></span>, atteinte <span><span class=\"nc-red nc-bold\">toxique</span></span></td><td><span><span class=\"nc-red nc-bold\">HTA</span></span>, <span>RA</span>, <span class=\"nc-red nc-bold\">CMH</span>, <span class=\"nc-orange nc-bold\">CMR</span>, péricardite <span>constrictive</span></td></tr>\n          <tr><td>Géométrie du VG</td><td>Dilatation — hypertrophie <strong><span>excentrique</span></strong></td><td>Parois épaissies et fibrosées — hypertrophie <strong><span><span class=\"nc-red nc-bold\">concentrique</span></span></strong></td></tr>\n          <tr><td>Conséquences</td><td><span class=\"nc-blue nc-bold\">VES ↓</span> → <span class=\"nc-blue nc-bold\">DC ↓</span> ; <span class=\"nc-blue nc-bold\">pressions de remplissage ↑</span> → <span><span class=\"nc-blue nc-bold\">VTD</span></span><span class=\"nc-blue nc-bold\"> ↑</span></td><td>VG rigide : toute ↑ de volume entraîne une ↑ de <span class=\"nc-red\">pression</span> diastolique</td></tr>\n        </tbody>\n      </table>\n      <p>Dans les deux cas, l'<strong>élévation des pressions de <span class=\"nc-red nc-bold\">remplissage</span> du VG</strong> est à l'origine de l'<span class=\"nc-yellow_bg nc-bold\">IC gauche</span> et de l'<span>œdème</span> pulmonaire.</p>\n      <p><strong>Remodelage et mécanismes compensateurs</strong> (présents quelle que soit la cause) — bénéfiques à court terme, <span>délétères à long terme</span> :</p>\n      <ul>\n        <li><strong>Cardiaques :</strong> ↑ fréquence cardiaque ; dilatation ventriculaire (surcharge de <span class=\"nc-yellow_bg nc-bold\">précharge</span>) ; hypertrophie ventriculaire (surcharge de postcharge).</li>\n        <li><strong>Extra-cardiaques (neuro-hormonaux) :</strong> activation du <span>système adrénergique</span> et du <span>SRAA</span> (rétention hydrosodée, vasoconstriction) — ce sont les cibles des traitements de l'IC.</li>\n      </ul>\n      <p><strong>IC droite :</strong> la 1ʳᵉ cause est l'<span><span class=\"nc-yellow_bg nc-bold\">IC gauche</span></span> (HTAP post-capillaire) ; viennent ensuite le <span>cœur pulmonaire</span> (pathologies pulmonaires via l'<span class=\"nc-red nc-bold\">hypoxémie</span>), l'<span><span class=\"nc-orange_bg\">IDM</span></span><span class=\"nc-orange_bg\"> du VD</span> et les valvulopathies droites.</p>\n      <div>Loi de Laplace : la contrainte pariétale augmente avec <span class=\"nc-red\">pression</span> et taille de la cavité, et diminue lorsque la paroi s’épaissit ; le coefficient dépend de la géométrie considérée.</div><p>FEVG = (VTD − VTS)/VTD. Une atteinte diastolique peut accompagner une FE réduite ; une FE préservée ne signifie pas absence de toute anomalie systolique.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":1},{"id":"234-6","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la différence entre OAP cardiogénique et OAP lésionnel","contenu":"<div class=\"notion-course\"><table><thead><tr><th>Mécanisme</th><th>Hydrostatique cardiogénique</th><th>Lésionnel</th></tr></thead><tbody><tr><td>Origine</td><td>Augmentation de <span class=\"nc-red\">pression</span> en amont du cœur gauche.</td><td>Augmentation de perméabilité de la barrière alvéolo-capillaire.</td></tr><tr><td>Liquide</td><td>Relativement pauvre en protéines.</td><td>Relativement riche en protéines.</td></tr><tr><td>Contexte</td><td>IC, valvulopathie, ischémie, OAP hypertensif.</td><td>Sepsis, pneumonie, inhalation, etc. ; un SDRA répond à des critères spécifiques.</td></tr><tr><td>Diagnostic</td><td>Clinique, échographie et contexte ; pas de PCP imposée.</td><td>Arguments de lésion pulmonaire et absence d’explication entièrement hydrostatique.</td></tr></tbody></table><p>Une baisse de <span class=\"nc-red\">pression</span> oncotique peut favoriser un œdème, mais ne le rend pas cardiogénique. Des mécanismes mixtes sont possibles. Dans les deux cas : <span class=\"nc-red nc-bold\">hypoxémie</span>, effet shunt et diminution de <span class=\"nc-red nc-bold\">compliance</span> ; la présence d’un mécanisme lésionnel ne permet pas à elle seule de nommer un SDRA.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":0},{"id":"234-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","contenu":"<div class=\"notion-course\"><p>Devant une <span>insuffisance respiratoire aiguë</span>, plusieurs diagnostics différentiels de l'<span><span class=\"nc-red nc-bold\">OAP</span></span><span class=\"nc-red nc-bold\"> cardiogénique</span> sont à évoquer. L'examen clinique oriente :</p>\n      <table>\n        <thead><tr><th>Pathologie</th><th><span>Terrain</span></th><th>Contexte</th><th>Inspection / auscultation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-red nc-bold\">OAP</span></span><span class=\"nc-red nc-bold\"> cardiogénique</span></strong></td><td>Sujet âgé</td><td>Ischémie myocardique, antécédent cardiaque, <span>HTA</span></td><td><span>Expectorations</span> <span>mousseuses rose saumoné</span>, <span><span class=\"nc-red nc-bold\">orthopnée</span></span> ; <span><span class=\"nc-red nc-bold\">râles</span></span><span class=\"nc-red nc-bold\"> </span><span><span class=\"nc-red nc-bold\">crépitants</span></span><span class=\"nc-red nc-bold\"> bilatéraux</span> symétriques</td></tr>\n          <tr><td><span>Pneumonie</span></td><td>Jeune ou âgé</td><td><span>Fièvre</span>, contexte <span>infectieux</span></td><td><span>Expectorations</span> <span>purulentes</span> ; <span>crépitants</span> unilatéraux en foyer</td></tr>\n          <tr><td>Exacerbation de <span>BPCO</span></td><td>Sujet âgé</td><td><span>Tabagisme</span>, bronchite chronique</td><td>Distension thoracique, lèvres pincées ; <span>sibilants</span></td></tr>\n          <tr><td>Crise d'<span>asthme</span></td><td>Sujet jeune</td><td>Antécédent asthmatique / <span>allergique</span></td><td>Freinage expiratoire marqué ; <span>sibilants diffus</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres causes d'<span>insuffisance respiratoire</span> aiguë</strong> à éliminer : <span>SDRA</span>, <span>embolie pulmonaire</span>, <span>tamponnade</span>, <span>épanchement pleural</span> ou <span>pneumothorax</span>, pneumopathie aiguë, insuffisance respiratoire décompensée.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span>Détresse</span> et <span>insuffisance respiratoire</span> aiguë · 226 — <span>Thrombose veineuse profonde</span> - EP · 235 — Péricardite aiguë · 154 — Infection bronchopulmonaire communautaire</em></p><div class=\"callout\"><p>Les profils se chevauchent : <span class=\"nc-red nc-bold\">sibilants</span> possibles dans l’OAP, crépitants parfois absents, OAP parfois unilatéral. Pneumonie et IC peuvent coexister ; fièvre, âge ou type d’expectoration ne suffisent pas à trancher.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":0},{"id":"234-8","rang":"B","rubrique":"Diagnostic positif","titre":"Différencier l’IC à FE diminuée et l’IC à FE conservée","contenu":"<div class=\"notion-course\"><h4>Comparer sans réduire le diagnostic à la FEVG</h4><table><thead><tr><th>Élément</th><th>FE diminuée</th><th>FE préservée</th></tr></thead><tbody><tr><td>Repère collège</td><td>≤ 40 % ; 41–49 % ancien groupe intermédiaire.</td><td>≥ 50 %.</td></tr><tr><td>Fonction</td><td>Dysfonction systolique dominante, souvent associée à dysfonction diastolique.</td><td>Pressions de <span class=\"nc-red nc-bold\">remplissage</span> élevées et anomalies de relaxation/<span class=\"nc-red nc-bold\">compliance</span> ; atteinte cardiaque objective à documenter.</td></tr><tr><td>Terrain fréquent</td><td>Ischémie, cardiomyopathie ; tout <span class=\"nc-red_bg\">âge</span>.</td><td><span class=\"nc-red_bg\">Âge</span>, HTA, <span class=\"nc-green_bg\">obésité</span>, FA, <span class=\"nc-orange\">diabète</span> et maladie rénale ; pas exclusivement féminin.</td></tr><tr><td>Traitements</td><td>Plusieurs classes réduisent événements et <span class=\"nc-green nc-bold\">mortalité</span> selon indication.</td><td>Diurétiques si congestion, traitement des comorbidités, SGLT2 et autres traitements selon recommandations/terrain.</td></tr></tbody></table><div class=\"callout\"><p><b>Actualisation ESC 2026.</b> Deux phénotypes : FEVG &lt; 50 % (HFrEF) et FEVG ≥ 50 % (HFpEF). La catégorie 41–49 % est intégrée à HFrEF. Les anciens seuils du collège restent indiqués comme repères pédagogiques datés ; ne pas mélanger les classifications.</p></div><p>Des signes typiques d’IC peuvent exister dans les deux groupes. Une amélioration de FEVG sous traitement ne signifie pas guérison et ne justifie pas son arrêt automatique.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details>","frequence":0},{"id":"234-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","contenu":"<div class=\"notion-course\"><h4>Présentation clinique et retentissement</h4><ul><li>Dyspnée d’effort, fatigue, orthopnée ou dyspnée paroxystique nocturne ; œdèmes et prise de poids peuvent témoigner de congestion.</li><li>Examen : crépitants, galop, <span class=\"nc-blue_bg\">turgescence jugulaire</span>/<span class=\"nc-blue_bg\">reflux hépato-jugulaire</span>, œdèmes déclives, <span class=\"nc-blue_bg\">hépatomégalie</span> ; signes parfois absents après traitement.</li><li>Rechercher hypoperfusion, souffle, irrégularité du rythme et facteurs déclenchants ; aucun signe isolé ne suffit.</li></ul><table><thead><tr><th>Classe NYHA</th><th>Limitation fonctionnelle</th></tr></thead><tbody><tr><td>I</td><td>Aucune limitation de l’activité physique habituelle.</td></tr><tr><td>II</td><td>Limitation légère : symptômes pour les efforts habituels, confortable au repos.</td></tr><tr><td>III</td><td>Limitation marquée : symptômes pour des efforts inférieurs à l’ordinaire, confortable au repos.</td></tr><tr><td>IV</td><td>Symptômes au repos ; toute activité augmente l’inconfort.</td></tr></tbody></table><h4>Hors urgence : suspicion clinique puis confirmation</h4><ol><li>Facteurs de risque, dyspnée/orthopnée, fatigue, œdèmes ; examen, constantes et ECG. Rechercher diagnostic différentiel et cause.</li><li>Peptides natriurétiques : repères du collège <span class=\"nc-pink_bg nc-bold\">BNP</span> &gt; 35 pg/mL ou <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> &gt; 125 pg/mL conduisant à poursuivre par échographie. Valeurs basses : IC moins probable, sans exclusion absolue si forte suspicion/<span class=\"nc-green_bg\">obésité</span>.</li><li>ETT : FEVG, cavités, cinétique, valves, fonction diastolique et pressions estimées. Une anomalie isolée sans syndrome clinique ne suffit pas à diagnostiquer une IC symptomatique.</li><li>Si discordance persistante : avis et examens ciblés, notamment pour IC à FE préservée ; <span class=\"nc-blue nc-bold\">FEVG</span> normale ou ETT de repos peu contributive ne suffisent pas à l’exclure.</li></ol><div class=\"callout\"><p>L’algorithme diagnostique du collège concerne la présentation non urgente. Devant un OAP ou un choc, soins et examens se font en parallèle.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":3},{"id":"234-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens dans le bilan d’une insuffisance cardiaque","contenu":"<div class=\"notion-course\"><p>Le bilan d'une IC associe des examens de 1ʳᵉ ligne (systématiques) et des examens de 2ᵉ ligne (orientation étiologique).</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><span>ECG</span></td><td>Rarement normal ; oriente l'étiologie (BBG, onde Q de <span>nécrose</span>, HVG) ; dépiste les <span class=\"nc-red nc-bold\">troubles du rythme</span> (<span>FA</span> ++)</td></tr>\n          <tr><td><span>Radiographie thoracique</span></td><td>Cardiomégalie (<span>RCT &gt; 0,5</span>) ; retentissement pleuropulmonaire. Son absence n'élimine pas le diagnostic</td></tr>\n          <tr><td><span><span class=\"nc-pink_bg nc-bold\">BNP</span> / <span class=\"nc-green_bg nc-bold\">NT-proBNP</span></span></td><td>Bonne valeur prédictive négative ; recommandés pour le diagnostic</td></tr>\n          <tr><td><span>ETT</span></td><td>Examen clé du <span>diagnostic positif</span> et étiologique</td></tr>\n          <tr><td><span>Biologie</span></td><td><span>NFS</span>, <span>ionogramme</span>, <span>créatininémie</span>, <span>bilan <span class=\"nc-blue_bg\">hépatique</span></span> ; <span>glycémie</span>, <span><span class=\"nc-blue_bg\">HbA1c</span></span>, <span><span class=\"nc-blue_bg\">bilan lipidique</span></span> ; TSHus ; bilan du <span class=\"nc-pink nc-bold\">fer</span> (<span class=\"nc-orange_bg\">carence martiale</span>, <span class=\"nc-orange\">hémochromatose</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Examens de 2ᵉ intention</strong> (selon le contexte étiologique) : coroscanner, <span>coronarographie</span>, <span>IRM cardiaque</span>, <span>scintigraphie</span> isotopique, <span class=\"nc-blue_bg\">cathétérisme</span> droit, <span><span class=\"nc-blue_bg\">Holter</span></span><span class=\"nc-blue_bg\">-</span><span><span class=\"nc-blue_bg\">ECG</span></span>, <span><span class=\"nc-blue_bg\">MAPA</span></span>, <span><span class=\"nc-blue_bg\">EFR</span></span>, <span class=\"nc-blue_bg\">test de marche de </span><span><span class=\"nc-blue_bg\">6 min</span></span>, <span>épreuve d'effort</span> avec mesure de la <span>VO₂</span>.</p><p>Bilan martial : <span class=\"nc-pink_bg\">ferritine</span> et coefficient de saturation de la transferrine, pas uniquement <span class=\"nc-pink nc-bold\">fer</span> sérique. Adapter le bilan étiologique à la clinique ; les examens de deuxième intention ne sont pas tous systématiques.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details>","frequence":2},{"id":"234-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","contenu":"<div class=\"notion-course\"><p>Le bilan confirme l’origine cardiaque, la gravité et le déclencheur pendant le traitement ; il ne doit pas en retarder le début.</p><table><thead><tr><th>Examen</th><th>Question</th></tr></thead><tbody><tr><td>ECG urgent</td><td>SCA, tachyarythmie, bradycardie/conduction.</td></tr><tr><td>Échographie cardiaque et pulmonaire si disponible</td><td>Fonction VG/VD, valves, complication mécanique, congestion ; ETT urgente si instabilité.</td></tr><tr><td>Radiographie thoracique</td><td>Congestion et diagnostics différentiels, en fonction de l’accès et sans retarder les soins.</td></tr><tr><td>Biologie</td><td>NFS, ionogramme, urée/créatinine ; bilan <span class=\"nc-blue_bg\">hépatique</span>, hémostase selon contexte. Troponine pour lésion myocardique et recherche de SCA.</td></tr><tr><td><span class=\"nc-pink_bg nc-bold\">BNP</span>/<span class=\"nc-green_bg nc-bold\">NT-proBNP</span></td><td>En dyspnée aiguë : <span class=\"nc-pink_bg nc-bold\">BNP</span> <span class=\"nc-red nc-bold\">&lt;</span><span class=\"nc-red nc-bold\"> 100 pg/mL</span> ou <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> &lt; 300 pg/mL rendent l’IC moins probable, avec limites. Le seuil 125 concerne la présentation chronique.</td></tr><tr><td>Gaz du sang / lactate</td><td>Détresse respiratoire, trouble ventilatoire, choc ou besoin d’évaluer acidose/hypercapnie. Pas un préalable systématique au traitement.</td></tr></tbody></table><p>Hypoxémie/hypocapnie initiale possibles ; hypercapnie en cas d’épuisement ou comorbidité ; acidose et lactate peuvent témoigner d’hypoperfusion.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":2},{"id":"234-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites du BNP ou du NT proBNP pour le diagnostic et le suivi","contenu":"<div class=\"notion-course\"><p><span class=\"nc-pink_bg nc-bold\">BNP</span> et NT-proBNP reflètent la contrainte pariétale myocardique. Ils aident au diagnostic, à la stratification pronostique et au suivi, sans se substituer à la clinique.</p><table><thead><tr><th>Contexte</th><th>Seuils d’exclusion usuels du collège</th></tr></thead><tbody><tr><td>Dyspnée aiguë</td><td><span class=\"nc-pink_bg nc-bold\">BNP</span> <span class=\"nc-red nc-bold\">&lt;</span><span class=\"nc-red nc-bold\"> 100 pg/mL</span> ou <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> &lt; 300 pg/mL : IC peu probable.</td></tr><tr><td>Suspicion chronique</td><td><span class=\"nc-pink_bg nc-bold\">BNP</span> &lt; 35 pg/mL ou NT-proBNP <span class=\"nc-red nc-bold\">&lt;</span><span class=\"nc-red nc-bold\"> 125 pg/mL</span> : IC peu probable.</td></tr></tbody></table><p>En dyspnée aiguë, repères de confirmation <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> : &gt; 450 pg/mL avant 50 ans, &gt; 900 entre 50 et 75 ans, &gt; 1 800 après 75 ans. Une valeur élevée ne prouve pas à elle seule une IC ; les algorithmes sont interprétés selon <span class=\"nc-red_bg\">âge</span>, contexte et méthode.</p><ul><li>Valeurs augmentées par <span class=\"nc-red_bg\">âge</span>, maladie rénale, FA, EP, SCA et autres états critiques.</li><li>Valeurs diminuées dans l’<span class=\"nc-green_bg\">obésité</span> ; possibles valeurs trompeusement faibles en OAP très précoce/flash ou certaines IC à FE préservée.</li><li>Sous <span class=\"nc-pink_bg\">sacubitril-valsartan</span>, le <span class=\"nc-pink_bg nc-bold\">BNP</span> peut être influencé par l’inhibition de la néprilysine ; <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> est préféré pour suivre la réponse. Le <span class=\"nc-pink_bg nc-bold\">BNP</span> n’est pas « toujours ininterprétable ».</li><li>Au suivi, confronter tendance, symptômes, poids, fonction rénale et échographie ; ne pas ajuster tous les traitements pour atteindre un chiffre isolé.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details><div class=\"callout\"><p>Schéma LiSA en dyspnée aiguë : BNP 100–400 ng/L = zone grise ; BNP > 400 ng/L = IC probable. Pour NT-proBNP, les seuils élevés dépendent de l’âge (450 / 900 / 1 800 ng/L). 1 ng/L = 1 pg/mL. Aux limites ou en cas de discordance, poursuivre l’évaluation clinique et échographique.</p></div>","frequence":0},{"id":"234-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la valeur de l’échocardiographie transthoracique dans le diagnostic positif et étiologique","contenu":"<div class=\"notion-course\"><p>L'<span>échocardiographie-doppler transthoracique (ETT)</span> est l'<strong>examen clé</strong> du <span>diagnostic positif</span> <strong>et</strong> étiologique de l'IC ; elle est aussi utile pour ajuster le traitement. Elle est indiquée si <span><span class=\"nc-pink_bg nc-bold\">BNP</span> &gt; 35 pg/mL</span> ou <span><span class=\"nc-green_bg nc-bold\">NT-proBNP</span> &gt; 125 pg/mL</span>, ou si l'IC est fortement suspectée.</p>\n      <p><strong>Renseignements apportés :</strong></p>\n      <ul>\n        <li>Taille du VG : diamètres (<span>DDVG</span>, <span>DSVG</span>) ou volumes (<span>VTD</span>, <span>VTS</span>).</li>\n        <li>FEVG : interpréter avec les valeurs normales du laboratoire, le sexe, la méthode et les autres paramètres échographiques ; ≥ 50 % définit le groupe FE préservée, sans prouver une fonction normale.</li>\n        <li>Taille et fonction du VD, taille de la veine cave inférieure, taille des atriums.</li>\n        <li>Aspect des valves ; niveau des pressions de <span class=\"nc-red nc-bold\">remplissage</span> (flux <span>doppler</span>).</li>\n        <li>Indices hémodynamiques : débit cardiaque, <span class=\"nc-red nc-bold\">pressions pulmonaires</span> ; diamètres de l'aorte thoracique.</li>\n        <li>Évaluation du <strong>péricarde</strong> (épanchement, constriction).</li>\n      </ul><div class=\"callout\"><p>FEVG et <span class=\"nc-red nc-bold\">remplissage</span> doivent être interprétés ensemble. Une FEVG ≥ 50 % n’exclut pas l’IC. Si suspicion persistante avec résultats de repos peu concluants, exploration spécialisée fonctionnelle/hémodynamique selon le contexte.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":2},{"id":"234-14","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","contenu":"<div class=\"notion-course\"><p>Les trois ensembles classiques de signes radiographiques correspondent à redistribution vasculaire, œdème interstitiel et œdème alvéolaire. Ils ne forment pas une succession obligatoire chez chaque patient.</p>\n      <table>\n        <thead><tr><th><span>Stade</span></th><th>Signes radiographiques</th></tr></thead>\n        <tbody>\n          <tr><td><span>Stade</span> 1 — redistribution vasculaire</td><td>Redistribution du flux vers les sommets : <span>égalisation du calibre</span> des vaisseaux de la base au sommet (évaluable seulement sur cliché debout)</td></tr>\n          <tr><td><span>Stade</span> 2 — <span>œdème</span> interstitiel</td><td><span>Lignes de Kerley B</span> (<span>œdème</span> des septums interlobulaires) ; <span>flou périhilaire</span> ; images réticulo-nodulaires basales ; apparition des scissures ; épanchements pleuraux</td></tr>\n          <tr><td><span>Stade</span> 3 — <span>œdème</span> alvéolaire</td><td><span>Opacités floconneuses</span> confluentes péri-hilaires <span>« en ailes de papillon »</span>, bilatérales (des formes unilatérales trompeuses existent)</td></tr>\n        </tbody>\n      </table>\n      <p>La <span>cardiomégalie</span> (rapport cardiothoracique <span>&gt; 0,5</span>) est fréquente, mais son absence n'élimine pas le diagnostic ; son interprétation reste prudente chez un patient alité.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade1-schema.png\" alt=\"Schéma du stade 1 radiologique de l&#x27;OAP — redistribution vasculaire vers les sommets\" loading=\"lazy\">\n        <figcaption><span>Stade</span> 1 : redistribution vasculaire vers les sommets. Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade2-schema.png\" alt=\"Schéma du stade 2 radiologique de l&#x27;OAP — œdème interstitiel, lignes de Kerley B\" loading=\"lazy\">\n        <figcaption><span>Stade 2</span> : <span>œdème</span> interstitiel (lignes de Kerley B, <span>flou périhilaire</span>). Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade3-schema.png\" alt=\"Schéma du stade 3 radiologique de l&#x27;OAP — œdème alvéolaire en ailes de papillon\" loading=\"lazy\">\n        <figcaption><span>Stade 3</span> : <span>œdème</span> alvéolaire péri-hilaire « en ailes de papillon ». Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 En cas d'<span>OAP</span> <strong>lésionnel</strong> (<span>SDRA</span>), la silhouette cardiaque est généralement <strong>normale</strong> (rapport cardiothoracique normal).</div><p>La radiographie peut être initialement peu contributive ; l’absence de cardiomégalie ou d’ailes de papillon n’exclut pas l’OAP.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":0},{"id":"234-15","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie thoracique d’un OAP d’origine hémodynamique","contenu":"<div class=\"notion-course\"><p>L'objectif « Contenu multimédia » attend la reconnaissance d'une <span>radiographie thoracique d'OAP d'origine hémodynamique</span> et la description de sa sémiologie.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-rxt-annotee-lecture.png\" alt=\"Radiographie thoracique d&#x27;un OAP cardiogénique annotée — opacités alvéolaires bilatérales péri-hilaires, lignes de Kerley B, cardiomégalie\" loading=\"lazy\">\n        <figcaption><span>Radiographie thoracique</span> d'un <span>OAP</span> d'origine hémodynamique, annotée pour la lecture. Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <p><strong>Signes à reconnaître sur le cliché :</strong></p>\n      <ul>\n        <li><span>Opacités alvéolaires</span> bilatérales, floconneuses, péri-hilaires, « en ailes de papillon ».</li>\n        <li><span>Redistribution vasculaire</span> vers les sommets.</li>\n        <li><span>Lignes de Kerley B</span> aux bases (<span>œdème</span> interstitiel).</li>\n        <li><span>Épanchements pleuraux</span> (comblement des culs-de-sac costodiaphragmatiques).</li>\n        <li><span>Cardiomégalie</span> — rapport cardiothoracique <span>&gt; 0,5</span>.</li>\n      </ul>\n      <div>La référence est un cliché debout postéro-antérieur. Au lit en antéropostérieur, agrandissement cardiaque, décubitus et qualité limitent le rapport cardiothoracique et la redistribution ; les autres signes restent interprétables avec prudence.</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li></ul><p></p></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/heart-failure-summary","label":"Radiopaedia : Heart failure summary"},{"href":"https://radiopaedia.org/articles/cardiogenic-pulmonary-oedema","label":"Radiopaedia : Cardiogenic pulmonary oedema"},{"href":"https://radiopaedia.org/articles/right-heart-strain","label":"Radiopaedia : Right heart strain"}]},{"id":"234-16","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies de l’IC","contenu":"<div class=\"notion-course\"><p>Toutes les pathologies cardiaques peuvent aboutir à une IC. Les étiologies se classent par <strong>structure atteinte</strong> :</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Coronaires</td><td><span><span class=\"nc-yellow_bg\">Cardiopathie ischémique</span></span> — <strong>1ʳᵉ cause d'<span class=\"nc-blue_bg\">IC à FEVG réduite</span></strong></td></tr>\n          <tr><td>Vaisseaux</td><td><span><span class=\"nc-red nc-bold\">HTA</span></span> — augmentation de la postcharge, <span class=\"nc-orange nc-bold\">HVG</span>, altération diastolique</td></tr>\n          <tr><td>Myocarde</td><td>Cardiomyopathies (<span>CMD</span>, <span><span class=\"nc-red nc-bold\">CMH</span></span>, <span><span class=\"nc-orange nc-bold\">CMR</span></span>) ; myocardites ; toxiques (<span>alcool</span>, <span><span class=\"nc-pink_bg\">anthracyclines</span></span>, <span><span class=\"nc-pink_bg\">trastuzumab</span></span>) ; cardiomyopathies <span>infiltratives</span> (<span><span class=\"nc-red nc-bold\">amylose cardiaque</span></span> — AL / à transthyrétine ATTR, <span>maladie de Fabry</span>, <span class=\"nc-orange\">hémochromatose</span>, <span class=\"nc-orange\">sarcoïdose</span>) ; carence en <span>thiamine (vitamine B1) — <span class=\"nc-orange_bg\">béribéri</span> humide</span></td></tr>\n          <tr><td>Valves</td><td>Valvulopathies (RAo, IM, IA, RM) ; <span>endocardite</span> infectieuse</td></tr>\n          <tr><td>Tissu cardionecteur</td><td><span class=\"nc-red nc-bold\">Troubles du rythme</span> (<span>FA rapide</span> → CMD rythmique), grande <span><span class=\"nc-orange nc-bold\">bradycardie</span></span>, troubles conductifs</td></tr>\n          <tr><td>Péricarde</td><td><span><span class=\"nc-orange nc-bold\">Péricardite constrictive</span></span>, épanchement abondant, <span><span class=\"nc-red_bg nc-bold\">tamponnade</span></span></td></tr>\n          <tr><td>Ventricule droit</td><td>Causes d'IC droite isolée (cœur pulmonaire, <span><span class=\"nc-orange_bg\">IDM</span></span><span class=\"nc-orange_bg\"> du VD</span>, valvulopathies droites)</td></tr>\n          <tr><td>Débit cardiaque élevé</td><td><span class=\"nc-orange_bg\">Anémie chronique</span>, <span><span class=\"nc-orange_bg\">hyperthyroïdie</span></span>, <span class=\"nc-orange_bg\">béribéri</span>, <span class=\"nc-orange_bg\">maladie de Paget</span>, <span class=\"nc-orange_bg\">fistules artério-veineuses</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"nc-orange nc-bold\">Amylose cardiaque à transthyrétine</span> (LiSA).</strong> Étiologie sous-diagnostiquée de l'<span class=\"nc-green_bg\">IC à FEVG préservée</span> du sujet <span class=\"nc-pink_bg\">âgé</span>. Le diagnostic non invasif repose sur la <span>scintigraphie osseuse aux biphosphonates marqués (⁹⁹ᵐTc-HMDP / DPD / PYP)</span> : une fixation myocardique <strong>Perugini ≥ 2</strong>, associée à l'absence de composant monoclonal (électrophorèse + immunofixation sérique/urinaire + chaînes légères libres), permet de retenir le diagnostic d'ATTR sans biopsie endomyocardique.</div>\n      <p><strong>Respiration périodique de Cheyne-Stokes.</strong> Alternance de cycles d'<span>hyperpnée crescendo-decrescendo</span> et d'<span>apnées centrales</span> ; observée dans l'IC sévère (bas débit cérébral + hypersensibilité chémoréceptrice), elle est un marqueur de <span class=\"nc-blue_bg\">mauvais </span><span><span class=\"nc-blue_bg\">pronostic</span></span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 233 — Valvulopathie · 224 — <span>HTA</span> · 232 — <span><span class=\"nc-red_bg\">Fibrillation atriale</span></span></em></p><div class=\"callout\"><p><span class=\"nc-orange_bg\">Amylose</span> ATTR : interpréter la scintigraphie avec le phénotype cardiaque et rechercher une gammapathie par immunofixations sérique/urinaire et chaînes légères libres. Si composant monoclonal ou discordance, la scintigraphie seule ne suffit pas à exclure AL : avis spécialisé/typage tissulaire selon cas.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details>","frequence":1},{"id":"234-17","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités du diagnostic d’un OAP cardiogénique","contenu":"<div class=\"notion-course\"><h4>Reconnaître l’OAP</h4><ul><li>Dyspnée souvent rapide, <span class=\"nc-red nc-bold\">orthopnée</span>, polypnée, sueurs, angoisse ; toux et expectoration mousseuse parfois saumonée, hypoxémie. Présentation parfois progressive ou inaugurale.</li><li>Crépitants souvent bilatéraux ; <span class=\"nc-yellow_bg\">sibilants</span> ou asymétrie possibles. <span class=\"nc-red nc-bold\">Tachycardie</span> fréquente mais non <span class=\"nc-red nc-bold\">constante</span> ; rechercher une bradyarythmie déclenchante.</li><li>PA élevée, normale ou basse. Une poussée hypertensive peut être un mécanisme causal d’OAP, pas seulement une réaction au stress.</li></ul><h4>Gravité et cause</h4><ul><li>Épuisement, trouble de conscience, hypoxémie, fréquence respiratoire très élevée ou bradypnée ; préparer une assistance ventilatoire adaptée.</li><li>Hypoperfusion/choc, ischémie, trouble du rythme ou souffle nouveau : filière urgente et échographie.</li><li>Ne pas attendre l’échec d’un haut débit d’oxygène pour discuter une VNI en détresse respiratoire ; vérifier les contre-indications.</li></ul><p><span class=\"nc-red nc-bold\">Killip</span> est une classification de gravité de l’IC dans l’infarctus : I absence d’IC, II signes modérés, III OAP, IV choc. Ce n’est pas une simple carte de hauteur des crépitants.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":1},{"id":"234-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’urgence de l’OAP cardiogénique","contenu":"<div class=\"notion-course\"><h4>Traiter sur place, bilan en parallèle</h4><ol><li>Alerte et filière adaptée ; <span class=\"nc-green_bg\">position demi-assise</span> si tolérée, monitorage ECG/PA/SpO₂, voie veineuse. Pas de perfusion de <span class=\"nc-red nc-bold\">remplissage</span> systématique.</li><li>Oxygène si hypoxémie, notamment SpO₂ &lt; 90 %, adapté au terrain. Une <span class=\"nc-pink_bg\">oxygénothérapie</span> n’est pas systématique si saturation normale.</li><li>VNI précoce si détresse respiratoire/hypoxémie et patient coopérant/protégeant ses voies aériennes. Surveiller PA et réponse ; intuber si échec, épuisement, altération majeure de conscience ou impossibilité de protéger les voies aériennes.</li><li>Diurétique de l’anse IV si congestion : dose selon traitement antérieur, fonction rénale et réponse. Repère initial usuel chez patient naïf : <span class=\"nc-pink nc-bold\">furosémide</span> 20–40 mg IV ; si déjà traité, dose IV adaptée à la dose orale habituelle, souvent 1–2 fois celle-ci. Réévaluer diurèse et congestion, pas 80 mg imposés à tous.</li><li><span class=\"nc-brown_bg\">Dérivés nitrés</span> IV si PA le permet, particulièrement OAP hypertensif ; souvent envisagés pour PAS &gt; 110 mmHg. Éviter <span class=\"nc-orange_bg\">hypotension</span>, infarctus du VD/dépendance à précharge et association récente à inhibiteur PDE5.</li><li>Traiter le déclencheur : SCA, arythmie, HTA, infection, problème valvulaire ou interruption thérapeutique.</li></ol><h4>Précautions et réévaluation</h4><ul><li>La VNI n’est pas obligatoire dans tout OAP. Choc, vomissements, coma ou besoin d’intubation immédiate rendent sa stratégie différente.</li><li>Morphine non systématique : risques respiratoire et hémodynamique ; réserver aux situations sélectionnées.</li><li>Thromboprophylaxie si hospitalisation/immobilisation et risque pertinent, en tenant compte du saignement et d’une anticoagulation déjà prescrite.</li><li>Inotropes réservés à hypoperfusion/bas débit sélectionnés, souvent choc ; pas de traitement de routine d’un OAP congestif à PA préservée.</li><li>Surveiller PA, fréquence/SpO₂, conscience, diurèse, créatinine et K/Mg ; une amélioration rapide est possible, mais l’absence d’amélioration impose réévaluation.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418162b473dacad6a1d4f0?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · OAP cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":3},{"id":"234-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","contenu":"<div class=\"notion-course\"><p>Les mesures hygiéno-diététiques sont <strong>systématiques chez tous les patients</strong> insuffisants cardiaques.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Recommandations</th></tr></thead>\n        <tbody>\n          <tr><td>Régime hyposodé</td><td>Objectif : ne pas dépasser <span><span class=\"nc-pink nc-bold\">5-6 g/jour</span></span> de sel</td></tr>\n          <tr><td><span>Surveillance</span> du poids</td><td>Consulter rapidement si <span><span class=\"nc-red_bg nc-bold\">prise de poids</span> de 2-3 kg</span>, a fortiori si soudaine (en <span>2-3 jours</span>)</td></tr>\n          <tr><td><span>Tabac</span> / <span>alcool</span></td><td>Arrêt du <span>tabac</span> impératif ; <span>réduction</span> de l'<span>alcool</span> (surtout dans les CMD)</td></tr>\n          <tr><td>Activité physique</td><td>Activité régulière recommandée — le <span>repos strict est délétère</span> (<span class=\"nc-red nc-bold\">déconditionnement</span>)</td></tr>\n          <tr><td>Vaccinations</td><td><span class=\"nc-pink_bg\">Anti-grippale</span>, <span class=\"nc-pink_bg\">anti-pneumococcique</span>, anti-COVID-19</td></tr>\n          <tr><td><span>Grossesse</span></td><td>À risque (<span>pronostic</span> maternel engagé dans les formes sévères) ; contraception adaptée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong><span>Éducation thérapeutique</span> — 2 mémos :</strong> « <strong><span>EPON</span></strong> » = 4 principes (<span class=\"nc-green_bg\">Exercice</span> physique, se Peser, Observance, Ne pas trop saler) ; « <strong><span>EPOF</span></strong> » = 4 signes d'alerte (Essoufflement, <span class=\"nc-red_bg nc-bold\">Prise de poids</span>, <span>Œdèmes</span>, Fatigue).</div>\n      <p>La <strong><span>réadaptation cardiaque</span></strong> associe réentraînement physique, optimisation thérapeutique et <span>éducation thérapeutique</span>. La <strong>télésurveillance</strong> permet de dépister précocement une <span>décompensation</span> et d'éviter une <span>hospitalisation</span>.</p><p>Éviter surtout les excès de sel ; adapter les objectifs nutritionnels et la restriction hydrique à la congestion, la natrémie et la fragilité. Pas de restriction hydrique sévère systématique chez tout patient stable. Vaccinations selon calendrier en vigueur et situation individuelle ; organiser un plan écrit d’alerte et de suivi.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1242988/fr/guide-parcours-de-soins-insuffisance-cardiaque\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Parcours insuffisance cardiaque, 2014</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":0},{"id":"234-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","contenu":"<div class=\"notion-course\"><h4>Traitement de fond : introduire tôt, adapter et surveiller</h4><p>Le schéma du collège à quatre piliers concerne historiquement l’IC à FEVG ≤ 40 %. L’ESC 2026 étend HFrEF à FEVG &lt; 50 % ; les seuils propres aux médicaments/dispositifs et les RCP restent à respecter.</p><table><thead><tr><th>Classe</th><th>Principes</th></tr></thead><tbody><tr><td>IEC ou ARNI ; ARA2 si intolérance adaptée</td><td><span class=\"nc-pink_bg\">Sacubitril-valsartan</span> est une option majeure. Jamais avec IEC : délai d’au moins 36 h entre IEC et ARNI. Surveiller PA, créatinine et potassium.</td></tr><tr><td><span class=\"nc-pink_bg\">Bêtabloquant</span> validé</td><td><span class=\"nc-pink nc-bold\">Bisoprolol</span>, <span class=\"nc-pink nc-bold\">carvédilol</span>, <span class=\"nc-pink nc-bold\">métoprolol</span> succinate LP ou <span class=\"nc-pink nc-bold\">nébivolol</span> selon indication. Introduire chez un patient stable, à petite dose, puis titrer selon tolérance.</td></tr><tr><td>Antagoniste minéralocorticoïde</td><td>Spironolactone/éplérénone dans HFrEF ; surveiller potassium et fonction rénale. Ne pas assimiler toutes les molécules et indications.</td></tr><tr><td>SGLT2</td><td><span class=\"nc-pink nc-bold\">Dapagliflozine</span> ou <span class=\"nc-pink nc-bold\">empagliflozine</span> selon indication, y compris sans <span class=\"nc-orange\">diabète</span>. Attention déshydratation, infection génitale et <span class=\"nc-red_bg\">acidocétose</span> rare ; consignes de suspension temporaire selon situation aiguë/jeûne/chirurgie.</td></tr><tr><td>Diurétique de l’anse</td><td>Soulage la congestion ; dose dynamique selon volémie et réponse. Association séquentielle si résistance sous surveillance.</td></tr></tbody></table><h4>Actualisation ESC 2026 — FE préservée également traitable</h4><p>SGLT2 et antagoniste minéralocorticoïde sont recommandés dans l’IC symptomatique indépendamment de la FEVG ; le choix de MRA diffère selon phénotype, fonction rénale, potassium et cadre réglementaire. Traiter aussi HTA, FA, <span class=\"nc-green_bg\">obésité</span>, ischémie et cause spécifique. Cette actualisation est distincte de la figure thérapeutique du collège fondée sur ESC 2021.</p><h4>Traitements et dispositifs sélectionnés</h4><ul><li><span class=\"nc-brown_bg\">Ivabradine</span> : patient symptomatique, rythme sinusal, <span class=\"nc-pink nc-bold\">FEVG ≤ 35 %</span>, FC &gt; 70/min malgré traitement optimal/toléré selon indication. Réduit notamment les <span class=\"nc-green nc-bold\">hospitalisations</span> ; elle n’est pas purement symptomatique.</li><li>Digoxine/digitoxine, vériciguat ou <span class=\"nc-green_bg\">vasodilatateurs</span> : indications spécialisées ; digoxine à marge thérapeutique étroite, attention rein, K et interactions.</li><li>DAI : prévention secondaire, ou primaire chez des patients sélectionnés, notamment <span class=\"nc-pink nc-bold\">FEVG ≤ 35 %</span> persistante après ≥ 3 mois de traitement optimisé, avec espérance de vie fonctionnelle <span class=\"nc-pink nc-bold\">&gt; 1 an</span> ; délai après <span class=\"nc-orange nc-bold\">infarctus</span> à respecter.</li><li>CRT : selon FEVG, symptômes, rythme et largeur/morphologie du QRS ; bénéfice particulièrement avec BBG et QRS ≥ 150 ms. Ce n’est pas une indication fondée sur la FEVG seule.</li><li>Éviter AINS et médicaments aggravant l’IC ; <span class=\"nc-red nc-bold\">vérapamil</span>/<span class=\"nc-red nc-bold\">diltiazem</span> et antiarythmiques de classe I sont inadaptés à l’IC systolique significative.</li></ul><p>Réévaluer rapidement doses et tolérance ; poursuivre habituellement le traitement de fond même si <span class=\"nc-green nc-bold\">symptômes</span> et FEVG s’améliorent.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li><li><a href=\"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque 2026, diapositives officielles</a></li></ul><p></p></details>","frequence":3},{"id":"234-21","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications de l’IC et leur prise en charge","contenu":"<div class=\"notion-course\"><h4>Complications : reconnaître et agir</h4><table><thead><tr><th>Complication</th><th>Conduite</th></tr></thead><tbody><tr><td>Décompensations répétées / IC avancée / <span class=\"nc-red_bg\">cachexie</span></td><td>Rechercher cause réversible, observance, congestion et <span class=\"nc-brown_bg\">dénutrition</span> ; avis centre d’IC avancée, réadaptation, support et projet de soins.</td></tr><tr><td>Choc</td><td>Soins critiques, traitement causal et soutien adapté sans attendre.</td></tr><tr><td>Syndrome cardiorénal</td><td>Évaluer congestion, perfusion, médicaments et obstacle. Une hausse modérée isolée de créatinine n’impose pas l’arrêt automatique de tous les traitements.</td></tr><tr><td>Troubles K/Na</td><td>Évaluer gravité ECG/clinique, corriger cause et adapter médicaments/diurétiques avec surveillance.</td></tr><tr><td>TV/FV / <span class=\"nc-red nc-bold\">mort subite</span></td><td>Réanimation si arrêt ; rechercher cause, discuter DAI selon critères.</td></tr><tr><td>Thromboembolie</td><td>Anticoagulation si FA/indication précise ou thrombus, pas systématique pour toute IC en rythme sinusal ; prévention liée à hospitalisation selon risque.</td></tr><tr><td><span class=\"nc-orange_bg\">Anémie</span>/<span class=\"nc-orange_bg\">carence martiale</span>/SAOS</td><td>Documenter puis traiter selon indication, sans supplémentation aveugle.</td></tr></tbody></table><p><span class=\"nc-blue_bg\">Mauvais pronostic</span> : symptômes NYHA III–IV, admissions répétées, mauvaise tolérance thérapeutique, dysfonction VG/VD, <span class=\"nc-red nc-bold\">hyponatrémie</span>, congestion persistante, maladie rénale et faible capacité d’effort. Aucun chiffre isolé ne résume le pronostic.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941810bbfe0f1ab9c47cb14?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Physiopathologie - Étiologies d’IC</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181d4ad20f152d66aa316?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sémiologie de l’insuffisance cardiaque</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":1},{"id":"234-22","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités du diagnostic d’un choc cardiogénique","contenu":"<div class=\"notion-course\"><h4>Hypoperfusion + cause cardiaque probable</h4><ul><li>Extrémités froides, marbrures, oligurie, confusion, lactate élevé ; <span class=\"nc-orange_bg\">hypotension</span> fréquente mais une PA préservée ne l’exclut pas.</li><li>Signes congestifs parfois frustes ou absents, notamment atteinte droite. Rechercher SCA, valvulopathie/complication mécanique, myocardite et arythmie.</li><li>ECG 12 dérivations avec droites/postérieures selon contexte ; ETT urgente ; biologie dont lactate, fonction rénale, électrolytes et troponine.</li><li>Monitorage et hémodynamique invasive si nécessaire pour guider un choc complexe ; pas de préalable obligatoire au traitement.</li></ul><h4>Distinguer les mécanismes de choc</h4><table><thead><tr><th>Cause</th><th>Orientation</th></tr></thead><tbody><tr><td>Cardiogénique</td><td>Défaillance VG/VD, infarctus ou complication mécanique, <span class=\"nc-pink nc-bold\">myocardite</span>, arythmie.</td></tr><tr><td>EP grave</td><td>Choc obstructif ; dilatation VD à l’ETT dans le contexte, non diagnostique isolément.</td></tr><tr><td>Tamponnade</td><td>Choc obstructif : retentissement de l’épanchement, pas uniquement son volume.</td></tr><tr><td>Pneumothorax compressif</td><td>Obstruction avec détresse, abolition unilatérale du murmure ; décompression sans attendre si menaçant.</td></tr><tr><td>Dissection</td><td>Peut provoquer tamponnade, insuffisance aortique ou atteinte coronaire ; filière aortique urgente.</td></tr></tbody></table><div class=\"callout\"><p>Ne pas attendre 30 min de PAS &lt; 90 mmHg. Les seuils historiques index &lt; 2,2 et PAPO &gt; 15 sont des repères hémodynamiques, non une liste obligatoire dans chaque cas.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e79dc8c62b3d434362?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Choc cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li></ul><p></p></details>","frequence":0},{"id":"234-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement du choc cardiogénique","contenu":"<div class=\"notion-course\"><h4>Soins critiques et traitement causal immédiat</h4><ol><li>Activer cardiologie/réanimation et équipe de choc ; ECG, échographie, monitorage rapproché, accès vasculaires, PA invasive et suivi de diurèse selon gravité.</li><li>Oxygénation et ventilation adaptées ; réévaluer rapidement perfusion et lactate.</li><li>Volémie : petit test de <span class=\"nc-pink nc-bold\">remplissage</span> uniquement si sous-<span class=\"nc-pink nc-bold\">remplissage</span> probable et absence de congestion, avec réévaluation ; <span class=\"nc-pink nc-bold\">diurétiques</span> si congestion selon perfusion.</li><li>Si <span class=\"nc-orange_bg\">hypotension</span> menaçante, noradrénaline souvent privilégiée pour soutenir la pression. Un inotrope tel que <span class=\"nc-pink_bg\">dobutamine</span> peut être ajouté en cas de bas débit persistant ; choix et association selon profil, sans ordre universel « <span class=\"nc-pink_bg\">dobutamine</span> puis noradrénaline ».</li><li>Infarctus : revascularisation urgente de l’artère responsable ; ne pas généraliser une angioplastie multivaisseaux immédiate en choc. Complication mécanique/valvulaire : geste chirurgical/interventionnel spécialisé.</li><li>Choc réfractaire sélectionné : assistance temporaire, stratégie de récupération/assistance durable/greffe discutée par équipe spécialisée. Contre-pulsion intra-aortique et ECMO ne sont pas des traitements systématiques.</li></ol><p>Les chocs obstructifs ont leur traitement propre : drainage de tamponnade, décompression pleurale ou reperfusion d’EP selon indication. Corriger également arythmies et facteurs réversibles.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Insuffisance cardiaque (234)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e79dc8c62b3d434362?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Choc cardiogénique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Insuffisance cardiaque</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Insuffisance cardiaque, recommandations 2026</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Syndromes coronariens aigus, 2023</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"FE préservée","contenu":"<div class=\"notion-course\"><p>Elle n’exclut ni <span class=\"nc-red nc-bold\">insuffisance cardiaque</span> ni possibilité de traitement.</p></div>"},{"type":"piege","titre":"125 ou 300","contenu":"<div class=\"notion-course\"><p>Ne pas utiliser le seuil chronique de NT-proBNP pour l’OAP.</p></div>"},{"type":"piege","titre":"OAP individualisé","contenu":"<div class=\"notion-course\"><p>VNI, nitrés et diurétiques dépendent de la gravité, de la PA et du terrain.</p></div>"},{"type":"piege","titre":"Collège et ESC 2026","contenu":"<div class=\"notion-course\"><p>Les classifications sont datées et présentées séparément.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Confronter syndrome clinique, peptides et échographie.</li><li>Chercher la cause et les facteurs de décompensation.</li><li>OAP/choc : traiter pendant le bilan.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Congestion, perfusion et ventilation déterminent les soins urgents.</li><li>Traitement de fond adapté, titré et surveillé ; prise en charge de la cause et des comorbidités.</li><li>Éducation, réadaptation et suivi organisé.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>ECG, ETT, peptides, biologie dont rein/K et bilan martial.</li><li>Examens étiologiques ciblés.</li><li>Surveiller réponse clinique, diurèse et biologie.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte/","label":"CNEC · Insuffisance cardiaque ↗"},{"href":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/heart-failure/","label":"ESC · Insuffisance cardiaque, recommandations 2026 ↗"},{"href":"https://dam-assets.escardio.org/download/b2e587389baa11f185de06bdfb3e4be9","label":"ESC · Insuffisance cardiaque 2026, diapositives officielles ↗"},{"href":"https://www.has-sante.fr/jcms/c_1242988/fr/guide-parcours-de-soins-insuffisance-cardiaque","label":"HAS · Parcours insuffisance cardiaque, 2014 ↗"},{"href":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","label":"ESC · Syndromes coronariens aigus, 2023 ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Décompensation avec détresse ou hypoperfusion ?","detail":"<ul><li>Conscience, PA, SpO₂, respiration, extrémités et diurèse.</li></ul>","branches":[{"label":"Hypoperfusion / choc","to":"choc"},{"label":"Détresse congestive sans choc","to":"oap"},{"label":"Tableau moins sévère / doute","to":"bilan"}]},{"id":"choc","kind":"urgent","label":"Soins critiques et traitement causal urgent","detail":"<ul><li>ETT rapide, lactate, ECG ; rechercher SCA, complication mécanique ou arythmie.</li></ul>","branches":[{"label":"Soutien adapté","to":"soutien"}]},{"id":"soutien","kind":"urgent","label":"Restaurer perfusion selon profil","detail":"<ul><li>Vasopresseur/inotrope sélectionnés ; remplissage prudent seulement si indiqué, assistance à discuter.</li></ul>","branches":[]},{"id":"oap","kind":"urgent","label":"Oxygénation, ventilation et décongestion adaptées","detail":"<ul><li>O₂ si hypoxémie ; VNI si indiquée et tolérée ; diurétique IV si congestion.</li></ul>","branches":[{"label":"PA suffisante / OAP hypertensif","to":"vasodilatation"},{"label":"Pas d’indication / contre-indication","to":"surveiller"}]},{"id":"vasodilatation","kind":"decision","label":"Nitrés si appropriés","detail":"<ul><li>Pas si hypotension ou contre-indication ; réévaluer PA et symptômes.</li></ul>","branches":[{"label":"Surveillance","to":"surveiller"}]},{"id":"surveiller","kind":"decision","label":"Réévaluer rapidement la réponse","detail":"<ul><li>Respiration, PA, diurèse, reins/ions ; escalade si échec ou aggravation.</li></ul>","branches":[{"label":"Échec / aggravation","to":"escalade"},{"label":"Amélioration","to":"cause"}]},{"id":"escalade","kind":"urgent","label":"Renfort spécialisé et soins critiques","detail":"<ul><li>Voies aériennes, ventilation et soutien selon mécanisme ; inotropes non systématiques.</li></ul>","branches":[]},{"id":"bilan","kind":"decision","label":"IC cardiogénique ou autre cause ?","detail":"<ul><li>ECG, biologie/peptides, imagerie thoracique et ETT selon état.</li></ul>","branches":[{"label":"IC retenue","to":"cause"},{"label":"Autre cause / incertitude","to":"differentiel"}]},{"id":"differentiel","kind":"uncertain","label":"Traiter le diagnostic retenu et réévaluer","detail":"<ul><li>Pneumonie, BPCO/asthme, EP, OAP lésionnel ; causes combinées possibles.</li></ul>","branches":[]},{"id":"cause","kind":"decision","label":"Rechercher et traiter cause / déclencheur","detail":"<ul><li>SCA, infection, HTA, trouble du rythme, valve, iatrogénie ou écart thérapeutique.</li></ul>","branches":[{"label":"Après stabilisation","to":"sortie"}]},{"id":"sortie","kind":"finish","label":"Optimiser le fond et organiser le suivi précoce","detail":"<ul><li>Éducation, poids/symptômes, ordonnance, contrôle rénal/ionique et réadaptation.</li></ul>","branches":[]}]},"cards":[{"i":"5a0519765f2d","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quelle est l'utilité des troponines et du BNP/NT-proBNP en urgence face à un OAP cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Troponine : lésion myocardique ; une élévation seule ne prouve pas un SCA.</li><li>En dyspnée aiguë, <span class=\"nc-pink_bg nc-bold\">BNP</span> &lt; 100 ou <span class=\"nc-green_bg nc-bold\">NT-proBNP</span> &lt; 300 pg/mL rendent l’IC moins probable, sans exclusion absolue si contexte trompeur. 125 pg/mL concerne la suspicion chronique.</li></ul></div>"},{"i":"95e4fe0eb8c1","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Que révèle l'analyse des gaz du sang artériel en urgence devant un OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>L'analyse des <span class=\"nc-blue_bg\">gaz du sang artériel</span> peut révéler :</p><ul><li>Un <strong>effet shunt</strong>, se manifestant par une <strong>hypoxie</strong> et une <strong>hypocapnie</strong> (par hyperventilation compensatrice).</li><li>Une <strong>hypercapnie</strong> si le patient présente un épuisement respiratoire.</li><li>Une <strong>acidose métabolique</strong> si l'OAP est associé à un état de choc.</li></ul></div>"},{"i":"c8a3e79ff91f","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quand l'ECG, la radiographie thoracique et l'échographie transthoracique sont-ils indiqués en urgence face à un OAP cardiogénique, et que recherchent-ils ?","a":"<div class=\"notion-course\"><ul><li>ECG urgent pour ischémie/arythmie. ETT, particulièrement urgente si instabilité, pour fonction et cause.</li><li>Radiographie/échographie pulmonaire selon disponibilité pour congestion et diagnostics différentiels, sans retarder les soins.</li></ul></div>"},{"i":"d24340a3fb65","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quels examens biologiques initiaux sont systématiquement demandés en urgence devant un OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>Les examens biologiques initiaux en urgence comprennent :</p><ul><li>Une <strong>NFS</strong> (Numération Formule Sanguine)</li><li>Un <strong>ionogramme sanguin</strong></li><li>L'<strong>urée</strong> et la <strong>créatinine</strong></li><li>Un <strong>bilan <span class=\"nc-blue_bg\">hépatique</span></strong></li><li>Un <strong><span class=\"nc-blue_bg\">TP / TCA</span></strong> (Temps de Quick / Temps de Céphaline Activée)</li></ul></div>"},{"i":"366722a0b2c3","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques sont observés au stade 3 (œdème alvéolaire) de la radiographie dans un OAP d'origine hémodynamique ?","a":"<div class=\"notion-course\"><p>Le stade 3 d'œdème alvéolaire est caractérisé par des <strong>opacités floconneuses confluentes péri-hilaires</strong>, classiquement décrites « <strong>en ailes de papillon</strong> ». Elles sont généralement bilatérales, bien que des formes unilatérales existent.</p></div>"},{"i":"3df0600dfe70","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quelle est l'importance de la cardiomégalie à la radiographie thoracique dans le diagnostic d'OAP d'origine hémodynamique ?","a":"<div class=\"notion-course\"><p>La <strong>cardiomégalie</strong> (rapport cardiothoracique supérieur à <strong>0,5</strong>) est fréquente mais <strong>son absence n'élimine pas le diagnostic</strong> d'OAP d'origine hémodynamique. Son interprétation doit être prudente chez un patient alité.</p></div>"},{"i":"bf4e2d1f701c","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques caractérisent le stade 1 de la radiographie dans un OAP d'origine hémodynamique ?","a":"<div class=\"notion-course\"><p>Le stade 1 correspond à une <strong>redistribution vasculaire</strong> avec une <strong>égalisation du calibre des vaisseaux de la base au sommet</strong>, évaluable sur un cliché debout.</p></div>"},{"i":"e9971787389d","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques caractérisent le stade 2 (œdème interstitiel) de la radiographie dans un OAP d'origine hémodynamique ?","a":"<div class=\"notion-course\"><p>Le stade 2 d'œdème interstitiel est caractérisé par :</p><ul><li>Les <strong>lignes de Kerley B</strong> (œdème des septums interlobulaires).</li><li>Un <strong>flou périhilaire</strong>.</li><li>Des images réticulo-nodulaires basales.</li><li>L'apparition des scissures.</li><li>Des <strong>épanchements pleuraux</strong>.</li></ul></div>"},{"i":"f7785d682533","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels sont les stades évolutifs de la radiographie thoracique dans un œdème aigu du poumon (OAP) d'origine hémodynamique ?","a":"<div class=\"notion-course\"><p>Redistribution vasculaire, œdème interstitiel puis alvéolaire sont trois ensembles classiques de signes. Leur succession n’est pas obligatoire et le cliché peut être initialement peu contributif.</p></div>"},{"i":"cd686dd0fced","n":234,"o":"234-15","u":"Contenu multimédia","t":"Radiographie thoracique d’un OAP d’origine hémodynamique","q":"Quels sont les signes radiologiques évocateurs d'un œdème aigu du poumon (OAP) d'origine hémodynamique sur une radiographie thoracique ?","a":"<div class=\"notion-course\"><p>Les signes radiologiques sont :</p><ul><li>Des <strong>opacités alvéolaires bilatérales</strong>, d'aspect <strong>floconneux</strong>, prédominant en région <strong><span class=\"nc-purple_bg\">péri-hilaire</span></strong>, souvent décrites « <strong>en ailes de papillon</strong> ».</li><li>Une <strong>redistribution vasculaire</strong> vers les sommets pulmonaires.</li><li>La présence de <strong>lignes de Kerley B aux bases</strong> (signe d'œdème interstitiel).</li><li>Des <strong>épanchements pleuraux</strong>, se manifestant par un comblement des culs-de-sac costo-diaphragmatiques.</li><li>Une <strong>cardiomégalie</strong>, définie par un rapport cardiothoracique <strong>supérieur à 0,5</strong>.</li></ul></div>"},{"i":"eb9317a290ad","n":234,"o":"234-15","u":"Contenu multimédia","t":"Radiographie thoracique d’un OAP d’origine hémodynamique","q":"Dans quelles conditions de réalisation une radiographie thoracique permet-elle une interprétation fiable du rapport cardiothoracique et de la redistribution vasculaire pour le diagnostic d'OAP hémodynamique ?","a":"<div class=\"notion-course\"><p>Cliché PA debout de référence. Au lit en AP, agrandissement et décubitus limitent rapport cardiothoracique/redistribution ; interpréter avec prudence, sans déclarer tout le cliché inutilisable.</p></div>"},{"i":"15e3ef17e63e","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte du myocarde ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>cardiomyopathies</strong> (dilatée, hypertrophique, restrictive).</li><li>Les <strong>myocardites</strong>.</li><li>Les <strong>toxiques</strong> : <strong>alcool</strong>, <strong><span class=\"nc-pink_bg\">anthracyclines</span></strong>.</li></ul></div>"},{"i":"3c269ee7e57d","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte des valves cardiaques ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>valvulopathies</strong> : <strong>rétrécissement aortique (RAo)</strong>, <strong>insuffisance mitrale (IM)</strong>, <strong>insuffisance aortique (IA)</strong>, <strong>rétrécissement mitral (RM)</strong>.</li><li>L'<strong>endocardite infectieuse</strong>.</li></ul></div>"},{"i":"46db8707e522","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte des vaisseaux ?","a":"<div class=\"notion-course\"><p>L'<strong>hypertension artérielle (<span class=\"nc-red nc-bold\">HTA</span>)</strong> est la principale étiologie de l'<span class=\"nc-red nc-bold\">insuffisance cardiaque</span> liée à l'atteinte des vaisseaux, entraînant une augmentation de la postcharge, une hypertrophie ventriculaire gauche (<span class=\"nc-orange nc-bold\">HVG</span>) et une altération diastolique.</p></div>"},{"i":"8ac6e2aea632","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque dues à un cœur pulmonaire ou à des atteintes du ventricule droit ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>cœur pulmonaire</strong>.</li><li>L'<strong>infarctus du myocarde <span class=\"nc-yellow_bg\">du ventricule</span> droit (<span class=\"nc-orange_bg\">IDM du VD</span>)</strong>.</li><li>Les <strong>valvulopathies droites</strong>.</li></ul></div>"},{"i":"ac111072bce0","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque à débit cardiaque élevé ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-orange_bg\">anémie chronique</span></strong>.</li><li>L'<strong><span class=\"nc-orange_bg\">hyperthyroïdie</span></strong>.</li><li>Le <strong><span class=\"nc-orange_bg\">béribéri</span></strong>.</li><li>La <strong><span class=\"nc-orange_bg\">maladie de Paget</span></strong>.</li><li>Les <strong><span class=\"nc-orange_bg\">fistules artério-veineuses</span></strong>.</li></ul></div>"},{"i":"adc46dd3ed9b","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelle est la principale étiologie de l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche (FEVG) réduite ?","a":"<div class=\"notion-course\"><p>La principale étiologie de l'<span class=\"nc-red nc-bold\">insuffisance cardiaque</span> à <span class=\"nc-blue nc-bold\">FEVG</span> réduite est la <strong><span class=\"nc-yellow_bg\">cardiopathie ischémique</span></strong> (d'origine coronaire).</p></div>"},{"i":"c4aa3d274472","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte du tissu cardionecteur ?","a":"<div class=\"notion-course\"><ul><li>Les <strong><span class=\"nc-red nc-bold\">troubles du rythme</span> cardiaque</strong>, notamment la <strong><span class=\"nc-red_bg\">fibrillation atriale</span> (FA) rapide</strong> pouvant induire une cardiomyopathie rythmique.</li><li>Les <strong>grandes bradycardies</strong>.</li><li>Les <strong>troubles conductifs</strong>.</li></ul></div>"},{"i":"682cc62748b9","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les signes physiques à rechercher à l'examen clinique d'un patient présentant un OAP cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Crépitants souvent bilatéraux, parfois <span class=\"nc-yellow_bg\">sibilants</span> ou asymétrie ; <span class=\"nc-red nc-bold\">tachycardie</span> fréquente mais non <span class=\"nc-red nc-bold\">constante</span>.</li><li>PA élevée, normale ou basse ; une poussée hypertensive peut déclencher l’OAP.</li><li>Rechercher congestion droite, hypoperfusion et cause ; <span class=\"nc-red nc-bold\">Killip</span> est une classification de gravité post-infarctus.</li></ul></div>"},{"i":"80e5aff126bc","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les principaux symptômes rapportés par le patient en cas d'OAP cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Une <strong><span class=\"nc-red nc-bold\">polypnée superficielle</span></strong> et une <strong><span class=\"nc-red nc-bold\">orthopnée</span></strong> (le patient s'assoit, jambes pendantes pour respirer).</li><li>Une <strong>toux</strong> avec expectoration <strong>mousseuse blanchâtre ou saumonée</strong>.</li><li>Un <strong><span class=\"nc-yellow_bg\">grésillement laryngé</span></strong>.</li><li>Des <strong>sueurs et une angoisse</strong>.</li><li>Une <strong>cyanose</strong>.</li><li>Une <strong><span class=\"nc-blue nc-bold\">douleur</span> <span class=\"nc-blue nc-bold\">angineuse</span></strong> est possible.</li></ul></div>"},{"i":"b212a745a564","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quelle est la présentation typique d'un OAP cardiogénique, notamment concernant son installation ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">OAP cardiogénique</span> se caractérise par un tableau de <strong>détresse respiratoire de survenue brutale</strong>, souvent <strong>nocturne</strong>. Il peut même être inaugural chez un patient sans cardiopathie connue.</p></div>"},{"i":"c0e9ecf8a0b0","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les signes de gravité à identifier rapidement en cas d'OAP cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Hypoxémie, détresse ou épuisement respiratoire, troubles de conscience, hypoperfusion/choc, SCA ou arythmie menaçante.</li><li>Discuter précocement VNI si indiquée et sans contre-indication ; ne pas attendre l’échec d’un haut débit d’O₂.</li></ul></div>"},{"i":"43dc29e26641","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelle est une caractéristique de l'amélioration de l'OAP cardiogénique sous traitement et l'un des principaux pièges thérapeutiques ?","a":"<div class=\"notion-course\"><ul><li>L’amélioration peut être rapide sous traitement adapté, sans constituer un test diagnostique suffisant.</li><li>Pas d’inotrope de routine pour un OAP congestif ; réserver aux états sélectionnés de bas débit/hypoperfusion, en particulier choc, sous surveillance spécialisée.</li></ul></div>"},{"i":"6cf37fc4190d","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelles sont les mesures de mise en condition immédiates pour un OAP cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Alerte, demi-assise si tolérée, voie veineuse, monitorage ECG/PA/SpO₂.</li><li>O₂ si hypoxémie ; ventilation selon gravité. Pas de morphine ou de <span class=\"nc-red nc-bold\">remplissage</span> systématiques.</li></ul></div>"},{"i":"8e82e34b94d3","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quels sont les traitements médicamenteux spécifiques de l'OAP cardiogénique et leurs posologies/modes d'administration ?","a":"<div class=\"notion-course\"><ul><li>Diurétique de l’anse IV si congestion, dose individualisée : repère naïf <span class=\"nc-pink nc-bold\">furosémide</span> 20–40 mg ; tenir compte de la dose antérieure et des reins.</li><li>Nitrés si PA suffisante, notamment OAP hypertensif, avec surveillance et contre-indications.</li><li>Thromboprophylaxie selon immobilisation/risques, non automatique si contre-indication ou anticoagulation déjà en cours.</li></ul></div>"},{"i":"973ece4fac9c","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quel est le rôle de la ventilation dans la prise en charge d'urgence de l'OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>VNI précoce si détresse/hypoxémie et patient adapté ; pas dans tous les OAP. Intubation si échec, épuisement ou impossibilité de protéger les voies aériennes. Surveiller la pression artérielle.</p></div>"},{"i":"ada98203a46f","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelle est la stratégie générale du traitement d'urgence de l'OAP cardiogénique et quand doit-il être initié ?","a":"<div class=\"notion-course\"><p>La stratégie vise à assurer l'<strong>oxygénation</strong> et à réduire la <strong>pression hydrostatique capillaire pulmonaire</strong> (baisse de la précharge et de la postcharge). Le traitement doit être démarré <strong>sur place</strong>, souvent avant les premiers examens complémentaires.</p></div>"},{"i":"cf6ea20d9141","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quand les dérivés nitrés sont-ils contre-indiqués dans l'OAP cardiogénique et quel est l'effet secondaire à surveiller pour le furosémide ?","a":"<div class=\"notion-course\"><ul><li>Les <span class=\"nc-brown_bg\">dérivés nitrés</span> sont contre-indiqués si la <strong>PAS est inférieure à 100-110 mmHg</strong>.</li><li>L'effet secondaire à surveiller avec le <span class=\"nc-pink nc-bold\">furosémide</span> est l'<strong><span class=\"nc-red_bg\">hypokaliémie</span></strong>.</li></ul></div>"},{"i":"2148b0200da8","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quels sont les principes clés de l'éducation thérapeutique du patient insuffisant cardiaque, comprenant les principes de gestion et les signes d'alerte ?","a":"<div class=\"notion-course\"><p>Les principes clés de l'éducation thérapeutique sont résumés par deux mémos :</p><ul><li><strong>« EPON »</strong> pour les 4 principes de gestion : <strong><span class=\"nc-green_bg\">E</span></strong><span class=\"nc-green_bg\">xercice</span> physique, se <strong>P</strong>eser, <strong>O</strong>bservance thérapeutique, <strong>N</strong>e pas trop saler.</li><li><strong>« EPOF »</strong> pour les 4 signes d'alerte de décompensation : <strong>E</strong>ssoufflement, <strong>P</strong>rise de poids, <strong>Œ</strong>dèmes, <strong>F</strong>atigue.</li></ul></div>"},{"i":"4648c845d052","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quelles sont les autres mesures hygiéno-diététiques essentielles à discuter avec un patient insuffisant cardiaque ?","a":"<div class=\"notion-course\"><p>Les autres mesures hygiéno-diététiques essentielles sont :</p><ul><li>L'<strong>arrêt impératif du tabac</strong> et la <strong>réduction de l'alcool</strong> (surtout dans les cardiomyopathies <span class=\"nc-red nc-bold\">dilatées</span>).</li><li>Une <strong>activité physique régulière recommandée</strong> (le repos strict est délétère).</li><li>La réalisation des <strong>vaccinations</strong> (<span class=\"nc-pink_bg\">anti-grippale</span>, <span class=\"nc-pink_bg\">anti-pneumococcique</span>, anti-COVID-19).</li><li>Une contraception adaptée, car la <strong>grossesse est à risque</strong> et le pronostic maternel peut être engagé dans les formes sévères d'insuffisance cardiaque.</li></ul></div>"},{"i":"82d6944c9ca3","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quelles sont les mesures hygiéno-diététiques systématiques recommandées chez un patient insuffisant cardiaque pour la prise de son régime alimentaire et le suivi de son poids ?","a":"<div class=\"notion-course\"><p>Pour un patient insuffisant cardiaque, les mesures hygiéno-diététiques relatives au régime alimentaire et au poids sont :</p><ul><li>Un <strong>régime hyposodé</strong> avec pour objectif de ne pas dépasser <strong><span class=\"nc-pink nc-bold\">5-6 g/jour</span> de sel</strong>.</li><li>Une <strong>surveillance du poids</strong> avec la consigne de consulter rapidement en cas de <span class=\"nc-red_bg nc-bold\">prise de poids</span> de <strong>2-3 kg</strong>, à fortiori <span class=\"nc-red nc-bold\">si elle est soudaine</span> (en <strong>2-3 jours</strong>).</li></ul></div>"},{"i":"d66a17a58e98","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"En quoi consiste la réadaptation cardiaque et quel rôle joue la télésurveillance dans la prise en charge de l'insuffisance cardiaque ?","a":"<div class=\"notion-course\"><p>La <strong>réadaptation cardiaque</strong> associe le <strong>réentraînement physique</strong>, l'<strong>optimisation thérapeutique</strong> et l'<strong>éducation thérapeutique</strong>. La <strong>télésurveillance</strong> est un outil permettant de <strong>dépister précocement une décompensation</strong> et ainsi d'<strong>éviter une hospitalisation</strong>.</p></div>"},{"i":"193253a9c840","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Quels sont les seuils de FEVG de la classification historique du collège ?","a":"<div class=\"notion-course\"><ul><li>Réduite ≤ 40 % ; intermédiaire/légèrement réduite 41–49 % ; préservée ≥ 50 %.</li><li>Actualisation ESC 2026 distincte : HFrEF &lt; 50 %, HFpEF ≥ 50 %.</li></ul></div>"},{"i":"26adf34752bb","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Quels sont les critères diagnostiques spécifiques de l'Insuffisance Cardiaque à FEVG préservée (ICFEVp) ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue_bg\">Symptômes</span>/signes compatibles + FEVG ≥ 50 % + arguments objectifs de dysfonction ou de pressions de <span class=\"nc-red nc-bold\">remplissage</span> élevées. Échographie et peptides orientent ; un <span class=\"nc-pink_bg nc-bold\">BNP</span> peu élevé chez une personne obèse ne suffit pas à exclure.</p></div>"},{"i":"b979a3b8fa2c","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Quelle est la définition générale de l'insuffisance cardiaque ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">insuffisance cardiaque</span> est un <strong>syndrome clinique</strong> caractérisé par des <span class=\"nc-blue_bg\">symptômes</span> (<strong>dyspnée, œdème des chevilles, fatigue</strong>) et parfois des <span class=\"nc-blue_bg\">signes cliniques</span> (<strong><span class=\"nc-orange_bg\">tachycardie</span>, crépitants, <span class=\"nc-blue_bg\">turgescence jugulaire</span></strong>).</p><p>Ces manifestations sont dues à une <strong>anomalie de structure et/ou de fonction du cœur</strong>, qui entraîne un <strong><span class=\"nc-red nc-bold\">débit cardiaque insuffisant</span></strong> et/ou des <strong><span class=\"nc-red nc-bold\">pressions intracardiaques augmentées</span></strong>, <span class=\"nc-red nc-bold\">à l'effort</span> ou au <span class=\"nc-red nc-bold\">repos</span>.</p></div>"},{"i":"0c08a910cb09","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les précautions d'introduction des bêtabloquants dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"<div class=\"notion-course\">Dans l'IC-FEVG, les bêtabloquants sont introduits à <strong>doses très faibles</strong> chez un patient <strong>stabilisé</strong>, avec une <strong>augmentation progressive</strong> par paliers hebdomadaires.</div>"},{"i":"27b7db10ba29","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quels sont les dispositifs médicaux qui améliorent le pronostic dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"<div class=\"notion-course\">Les dispositifs médicaux qui améliorent le pronostic dans l'IC-FEVG sont la <strong>resynchronisation cardiaque (CRT)</strong> et le <strong>défibrillateur automatique implantable (DAI)</strong>.</div>"},{"i":"6373fcab86db","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les classes médicamenteuses qui améliorent le pronostic vital dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"<div class=\"notion-course\"><ul><li>Traitement de fond de l’<span class=\"nc-blue_bg\">IC à FEVG réduite</span> : IEC ou ARNI (pas ensemble), <span class=\"nc-pink_bg\">bêtabloquant</span> validé, antagoniste des minéralocorticoïdes et inhibiteur SGLT2.</li><li>Introduire et optimiser selon stabilité, PA, reins et kaliémie. ARA2 si IEC/ARNI inadaptés ; diurétique selon congestion.</li><li>Le cours distingue la classification du collège des recommandations ESC 2026.</li></ul></div>"},{"i":"77f20796f1b6","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les contre-indications médicamenteuses dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"<div class=\"notion-course\">Dans l'IC-FEVG, les contre-indications médicamenteuses sont :\n<ul>\n<li>Les <strong>inhibiteurs calciques bradycardisants</strong> (<span class=\"nc-red nc-bold\">diltiazem</span>, <span class=\"nc-red nc-bold\">vérapamil</span>).</li>\n<li>Les <strong>antiarythmiques de classe 1</strong> (<span class=\"nc-red nc-bold\">flécaïnide</span>).</li>\n<li>Les <strong><span class=\"nc-red nc-bold\">AINS</span></strong> (risque de rétention hydrosodée).</li>\n</ul></div>"},{"i":"9653474a0f67","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quels traitements soulagent la congestion et pourquoi l’ivabradine ne doit-elle pas être classée seulement symptomatique ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-brown_bg\">Diurétiques de l’anse</span>, parfois association thiazidique, soulagent la congestion.</li><li><span class=\"nc-brown_bg\">Ivabradine</span> réduit notamment les <span class=\"nc-green nc-bold\">hospitalisations</span> chez les patients répondant aux critères ; digoxine a aussi des indications sélectionnées.</li></ul></div>"},{"i":"29e8b82ff412","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les signes cliniques clés d'hypoperfusion périphérique et d'insuffisance cardiaque associés à un choc cardiogénique ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-orange_bg\">Hypotension</span></strong></li><li>Signes d'hypoperfusion périphérique : <strong>extrémités froides</strong>, <strong>marbrures</strong></li><li><strong>Oligurie</strong></li><li><strong>Altération de la conscience</strong></li><li><strong>Sueurs profuses</strong></li><li>Signes d'insuffisance cardiaque gauche, droite ou globale, le plus souvent associés.</li></ul></div>"},{"i":"b273f7925bc2","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les trois pièges diagnostiques à connaître concernant les signes cliniques du choc cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Congestion parfois fruste, hypoperfusion au premier plan.</li><li>Une PA préservée et l’absence d’œdèmes n’excluent pas le choc ; ne pas appliquer une proportion universelle.</li></ul></div>"},{"i":"d311f16cde17","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les examens complémentaires initiaux recommandés pour le diagnostic étiologique du choc cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>ECG 12 dérivations, complété par droites/postérieures si indiqué.</li><li>Biologie dont lactate/ionogramme/fonction rénale/troponine ; ETT urgente pour mécanisme et cause.</li></ul></div>"},{"i":"f0cc8df15c3f","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les critères hémodynamiques permettant de confirmer un choc cardiogénique, une fois une hypovolémie exclue ?","a":"<div class=\"notion-course\"><p>Repères classiques : index <span class=\"nc-pink nc-bold\">&lt;</span><span class=\"nc-pink nc-bold\"> 2,2 L/min/m²</span> et pressions de remplissage élevées, souvent <span class=\"nc-pink nc-bold\">PAPO &gt; 15 mmHg</span>. Ne pas attendre 30 min d’<span class=\"nc-orange_bg\">hypotension</span> ou ces mesures invasives : clinique et échographie guident les premiers soins.</p></div>"},{"i":"f66037e5a921","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Comment définir le choc cardiogénique, en distinguant ses deux composantes principales ?","a":"<div class=\"notion-course\"><p>Le choc cardiogénique associe un <strong><span class=\"nc-brown_bg\">état de choc</span></strong> et des <strong>signes d'insuffisance cardiaque</strong>.</p></div>"},{"i":"2c0136e2822c","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"Qu'est-ce qu'un œdème aigu pulmonaire (OAP) cardiogénique ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">OAP cardiogénique</span> est la <strong>manifestation la plus fréquente de l'<span class=\"nc-red nc-bold\">insuffisance cardiaque</span> aiguë</strong>. Il se caractérise par la diffusion de <strong>liquide plasmatique dans les espaces extravasculaires pulmonaires</strong> (interstitium et alvéoles), altérant l'hématose et entraînant une <strong><span class=\"nc-red nc-bold\">hypoxémie</span></strong>.</p></div>"},{"i":"3b6c12821355","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"Quel est le mécanisme hémodynamique conduisant à l'OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>Élévation de <span class=\"nc-red\">pression</span> hydrostatique en amont du cœur gauche dépassant les capacités de drainage ; liquide dans interstitium puis alvéoles, avec <span class=\"nc-red nc-bold\">hypoxémie</span>. Aucun seuil de PCP mesurée n’est obligatoire.</p></div>"},{"i":"f243dcd3929f","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"En quoi consiste le sub-œdème pulmonaire et quelle est sa valeur clinique ?","a":"<div class=\"notion-course\"><p>Le <strong>sub-œdème pulmonaire</strong> est une forme d'<span class=\"nc-red nc-bold\">OAP cardiogénique</span> en <strong>résolution rapide</strong>, mais il a la <strong>même valeur sémiologique</strong> que l'OAP. Il constitue une <strong>urgence</strong> car il présente un risque d'évolution vers une détresse respiratoire ou un collapsus.</p></div>"},{"i":"4b000a2d6d10","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Comment définit-on cliniquement le choc cardiogénique chez l'adulte ?","a":"<div class=\"notion-course\"><p>Le choc cardiogénique est caractérisé par l'<strong>incapacité du cœur à générer un débit sanguin suffisant</strong> pour répondre aux besoins métaboliques des organes périphériques, et ce <strong>après correction de la précharge</strong> (en l'absence d'hypovolémie).</p></div>"},{"i":"60e9bcde231f","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quels sont les critères hémodynamiques permettant de confirmer le diagnostic de choc cardiogénique, une fois l'hypovolémie exclue ?","a":"<div class=\"notion-course\"><p>Repères historiques : <span class=\"nc-orange_bg\">hypotension</span>, index <span class=\"nc-pink nc-bold\">&lt;</span><span class=\"nc-pink nc-bold\"> 2,2 L/min/m²</span>, <span class=\"nc-pink nc-bold\">PAPO &gt; 15 mmHg</span>. Non obligatoires dans tous les cas ; traiter l’hypoperfusion d’origine cardiaque sans attendre 30 min ni un cathétérisme.</p></div>"},{"i":"705f39dc0ed3","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quelle est la principale étiologie du choc cardiogénique chez l'adulte ?","a":"<div class=\"notion-course\"><p>L’infarctus est une cause majeure, avec la décompensation d’IC, les myocardites, arythmies et complications mécaniques/valvulaires. La proportion varie selon la cohorte.</p></div>"},{"i":"8e7bd8deef91","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quelles sont les conséquences physiopathologiques principales du choc cardiogénique sur les organes périphériques ?","a":"<div class=\"notion-course\"><p>La baisse du débit cardiaque entraîne :</p><ul><li>Une <strong>hypoperfusion</strong> tissulaire.</li><li>Une <strong>anoxie</strong> tissulaire.</li><li>Des défaillances des <strong>organes périphériques</strong> (rein, foie, cerveau).</li></ul></div>"},{"i":"7d190aa985c8","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Quels sont les principaux diagnostics différentiels de l'OAP cardiogénique à considérer devant une insuffisance respiratoire aiguë ?","a":"<div class=\"notion-course\"><p>Devant une insuffisance respiratoire aiguë, les principaux diagnostics différentiels de l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span> à considérer sont :</p><ul><li>la <strong>pneumonie</strong>,</li><li>l'<strong>exacerbation de BPCO</strong>,</li><li>la <strong>crise d'asthme</strong>,</li><li>le <strong>SDRA</strong>,</li><li>l'<strong>embolie pulmonaire</strong>,</li><li>la <strong>tamponnade</strong>,</li><li>l'<strong>épanchement pleural</strong> ou le <strong>pneumothorax</strong>,</li><li>la <strong>pneumopathie aiguë</strong>,</li><li>l'<strong>insuffisance respiratoire décompensée</strong>.</li></ul></div>"},{"i":"96174d894bc2","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une crise d'asthme d'un OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>La différenciation clinique entre une crise d'asthme et un <span class=\"nc-red nc-bold\">OAP cardiogénique</span> s'appuie sur :</p><ul><li>le <strong>terrain</strong> et le <strong>contexte</strong> : sujet jeune avec antécédent asthmatique ou allergique pour la crise d'asthme, versus sujet <span class=\"nc-red_bg\">âgé</span> avec ischémie myocardique, antécédent cardiaque ou HTA pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li><li>l'<strong>inspection/auscultation</strong> : freinage expiratoire marqué et <strong><span class=\"nc-red nc-bold\">sibilants</span> diffus</strong> pour la crise d'asthme, versus expectorations mousseuses rose saumoné, <span class=\"nc-red nc-bold\">orthopnée</span> et <strong><span class=\"nc-red nc-bold\">râles crépitants bilatéraux</span> symétriques</strong> pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li></ul><p>Les tableaux peuvent se chevaucher : sibilants possibles dans l’OAP et infection/IC peuvent coexister.</p></div>"},{"i":"a863a056e15d","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une exacerbation de BPCO d'un OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>La différenciation clinique entre une exacerbation de BPCO et un <span class=\"nc-red nc-bold\">OAP cardiogénique</span> s'appuie sur :</p><ul><li>le <strong>terrain</strong> et le <strong>contexte</strong> : sujet <span class=\"nc-red_bg\">âgé</span> avec tabagisme et bronchite chronique pour la BPCO, versus sujet <span class=\"nc-red_bg\">âgé</span> avec ischémie myocardique, antécédent cardiaque ou HTA pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li><li>l'<strong>inspection/auscultation</strong> : distension thoracique, lèvres pincées et <strong>sibilants</strong> pour la BPCO, versus expectorations mousseuses rose saumoné, <span class=\"nc-red nc-bold\">orthopnée</span> et <strong><span class=\"nc-red nc-bold\">râles crépitants bilatéraux</span> symétriques</strong> pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li></ul><p>Les tableaux peuvent se chevaucher : sibilants possibles dans l’OAP et infection/IC peuvent coexister.</p></div>"},{"i":"ff3656e045b5","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une pneumonie d'un OAP cardiogénique ?","a":"<div class=\"notion-course\"><p>La différenciation clinique entre une pneumonie et un <span class=\"nc-red nc-bold\">OAP cardiogénique</span> s'appuie sur :</p><ul><li>le <strong>terrain</strong> : jeune ou âgé pour la pneumonie, versus sujet âgé pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li><li>le <strong>contexte</strong> : fièvre, contexte infectieux pour la pneumonie, versus ischémie myocardique, antécédent cardiaque ou HTA pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li><li>l'<strong>inspection/auscultation</strong> : expectorations purulentes et crépitants unilatéraux en foyer pour la pneumonie, versus expectorations mousseuses rose saumoné, <span class=\"nc-red nc-bold\">orthopnée</span> et <span class=\"nc-red nc-bold\">râles crépitants bilatéraux</span> symétriques pour l'<span class=\"nc-red nc-bold\">OAP cardiogénique</span>.</li></ul><p>Les tableaux peuvent se chevaucher : sibilants possibles dans l’OAP et infection/IC peuvent coexister.</p></div>"},{"i":"0b0382362529","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quel examen biologique est utilisé en première intention pour orienter le diagnostic d'insuffisance cardiaque, et quels sont les seuils d'alerte ?","a":"<div class=\"notion-course\"><p>L'examen biologique utilisé est le <strong><span class=\"nc-blue_bg\">dosage des peptides natriurétiques</span> <span class=\"nc-pink_bg nc-bold\">BNP</span> ou <span class=\"nc-green_bg nc-bold\">NT-proBNP</span></strong>.</p><ul><li>Des valeurs de <strong><span class=\"nc-pink_bg nc-bold\">BNP</span> &gt; 35 pg/mL</strong> ou <strong>NT-proBNP &gt; 125 pg/mL</strong> doivent faire poursuivre les investigations.</li><li>Des valeurs normales rendent l'insuffisance cardiaque peu probable.</li></ul></div>"},{"i":"8b6d687044f5","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quelle est la première étape du diagnostic de l'insuffisance cardiaque, et quels éléments cliniques doivent être recherchés ?","a":"<div class=\"notion-course\"><p>La première étape diagnostique de l'insuffisance cardiaque est l'<strong>évaluation clinique</strong>.</p><ul><li>Rechercher les <strong>facteurs de risque</strong> : âge, hypertension artérielle (HTA), diabète, cardiopathie connue.</li><li>Évaluer les <strong><span class=\"nc-blue_bg\">symptômes</span> fonctionnels</strong> : dyspnée, fatigue, œdèmes des membres inférieurs.</li><li>Rechercher les <strong><span class=\"nc-blue_bg\">signes cliniques</span></strong> : <span class=\"nc-blue_bg\">turgescence jugulaire</span>, crépitants pulmonaires, <span class=\"nc-orange_bg\">tachycardie</span>, <span class=\"nc-blue_bg\">hépatomégalie</span>.</li></ul></div>"},{"i":"c6b8657867bc","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quel examen paraclinique est l'examen de référence pour confirmer ou infirmer une insuffisance cardiaque ?","a":"<div class=\"notion-course\"><p>L'examen de référence pour confirmer ou infirmer une insuffisance cardiaque est l'<strong>échocardiographie transthoracique (ETT)</strong>.</p><p>Elle permet d'évaluer :</p><ul><li>La <strong>fraction d'éjection ventriculaire gauche (FEVG)</strong>.</li><li>Une éventuelle <strong>dilatation ventriculaire</strong>.</li><li>Des <strong>troubles de relaxation</strong>.</li><li>Des <strong>valvulopathies</strong>.</li><li>Les <strong>pressions de <span class=\"nc-red nc-bold\">remplissage</span></strong>.</li></ul></div>"},{"i":"d9a8a75a199e","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Dans quelles situations peut-on conclure à une insuffisance cardiaque confirmée ou exclue après la démarche diagnostique séquentielle ?","a":"<div class=\"notion-course\"><p>Confronter syndrome clinique, peptides et anomalies cardiaques. Une FEVG normale ou une ETT de repos peu contributive n’exclut pas une IC à FE préservée ; poursuivre si suspicion persistante.</p></div>"},{"i":"28a6c50f6b32","n":234,"o":"234-1","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’insuffisance cardiaque","q":"L’IC à FE préservée est-elle dépourvue de traitements validés ?","a":"<div class=\"notion-course\"><ul><li>Non : traiter la congestion et les comorbidités ; SGLT2 et autres classes ont des indications démontrées.</li></ul></div>"},{"i":"725904df9905","n":234,"o":"234-5","u":"Eléments physiopathologiques","t":"Connaître la physiopathologie de l’IC (gauche et droite)","q":"De quoi dépendent le débit cardiaque et la fraction d’éjection ?","a":"<div class=\"notion-course\"><ul><li>DC = fréquence × VES ; <span class=\"nc-blue_bg\">VES = VTD − VTS</span> ; FEVG = VES/VTD. <span class=\"nc-yellow_bg nc-bold\">Précharge</span>, postcharge et contractilité influencent l’éjection.</li></ul></div>"},{"i":"fd2178b858e9","n":234,"o":"234-6","u":"Eléments physiopathologiques","t":"Connaître la différence entre OAP cardiogénique et OAP lésionnel","q":"Qu’est-ce qui distingue œdème hydrostatique et lésionnel ?","a":"<div class=\"notion-course\"><ul><li>Hydrostatique : <span class=\"nc-red\">pression</span> capillaire accrue ; lésionnel : perméabilité alvéolo-capillaire accrue. Des mécanismes mixtes existent.</li></ul></div>"},{"i":"7c97ae05c992","n":234,"o":"234-8","u":"Diagnostic positif","t":"Différencier l’IC à FE diminuée et l’IC à FE conservée","q":"Quels sont les deux phénotypes de FEVG dans l’ESC 2026 ?","a":"<div class=\"notion-course\"><ul><li>HFrEF : FEVG &lt; 50 % ; HFpEF : FEVG ≥ 50 %. Le groupe 41–49 % est intégré à HFrEF.</li><li>Conserver distinctement les seuils historiques du collège pour les questions se référant à cette classification.</li></ul></div>"},{"i":"ece40ded6980","n":234,"o":"234-10","u":"Examens complémentaires","t":"Connaître les principaux examens dans le bilan d’une insuffisance cardiaque","q":"Quel bilan martial demander dans l’IC ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Ferritine</span> et saturation de la transferrine ; le <span class=\"nc-pink nc-bold\">fer</span> sérique seul ne suffit pas.</li></ul></div>"},{"i":"681c67c1b08f","n":234,"o":"234-12","u":"Examens complémentaires","t":"Connaître l’intérêt et les limites du BNP ou du NT proBNP pour le diagnostic et le suivi","q":"Quels seuils de NT-proBNP ne faut-il pas confondre ?","a":"<div class=\"notion-course\"><ul><li>300 pg/mL pour rendre peu probable l’IC devant une dyspnée aiguë ; 125 pg/mL pour la suspicion chronique selon les repères du collège.</li><li>Interpréter avec âge, reins, FA et <span class=\"nc-green_bg\">obésité</span>.</li></ul></div>"},{"i":"55eed2e8642c","n":234,"o":"234-13","u":"Examens complémentaires","t":"Connaître la valeur de l’échocardiographie transthoracique dans le diagnostic positif et étiologique","q":"Une FEVG normale exclut-elle l’insuffisance cardiaque ?","a":"<div class=\"notion-course\"><ul><li>Non. Rechercher des signes objectifs d’IC à FE préservée et poursuivre si forte suspicion malgré une ETT de repos peu contributive.</li></ul></div>"},{"i":"bc31fc52fdcb","n":234,"o":"234-21","u":"Suivi et/ou pronostic","t":"Connaître les principales complications de l’IC et leur prise en charge","q":"Une augmentation modérée de créatinine impose-t-elle d’arrêter tous les traitements d’IC ?","a":"<div class=\"notion-course\"><ul><li>Non : évaluer congestion, perfusion, potassium, médicaments et évolution ; adapter individuellement.</li></ul></div>"},{"i":"27709965c7ca","n":234,"o":"234-23","u":"Prise en charge","t":"Connaître les principes du traitement du choc cardiogénique","q":"Faut-il toujours donner dobutamine avant noradrénaline dans le choc cardiogénique ?","a":"<div class=\"notion-course\"><ul><li>Non. <span class=\"nc-orange_bg\">Hypotension</span> menaçante : soutien vasopresseur, souvent noradrénaline ; bas débit persistant : inotrope selon profil, avec traitement causal.</li></ul></div>"},{"i":"bbb7b6f4dfae","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quel délai sépare un IEC de sacubitril-valsartan ?","a":"<div class=\"notion-course\"><ul><li>Au moins 36 heures ; pas d’association IEC + ARNI, avec surveillance PA, rein et potassium.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181199015ef78aa95f46e?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
